// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyoloji kuramları ve sosyologlar (orta).
const ozSocialscience6Orta = <(String, String, List<String>, String)>[
  ('Montesquieu\'nün "Kanunların Ruhu Üzerine" adlı eseri sosyolojinin öncüleri arasında sayılır. Bunun temel nedeni hangisidir?', 'Yasaları iklim, coğrafya ve toplumsal koşullarla ilişkilendirerek açıklaması', ['Toplumları yalnızca dinsel inançlara göre sınıflaması', 'İlk kez anket yöntemiyle nüfus verisi toplaması', 'Toplumsal olayların tek nedeninin bireylerin özgür iradesi ve kişisel tercihleri olduğunu savunması'], 'Montesquieu yasaların keyfî olmadığını, bir toplumun iklimi, coğrafyası, nüfusu ve gelenekleriyle bağlantılı olduğunu ileri sürdü. Toplumsal olguları koşullarına bağlama çabası onu sosyolojinin öncüleri arasına koyar.'),
  ('Auguste Comte gençliğinde yaklaşık yedi yıl boyunca hangi düşünürün sekreterliğini yapmış ve onun sanayi toplumu düşüncelerinden etkilenmiştir?', 'Henri de Saint-Simon', ['Alexis de Tocqueville', 'Joseph de Maistre', 'Pierre-Joseph Proudhon'], 'Comte 1817-1824 yılları arasında Saint-Simon\'un sekreteri ve yakın çalışma arkadaşıydı. Sonradan aralarında görüş ayrılığı çıksa da Comte\'un pozitivizmi bu dönemden izler taşır.'),
  ('Saint-Simon\'un gelecekteki toplum tasarımında toplumun yönetiminin kimlerin eline geçmesi gerektiği düşüncesi yer alır?', 'Sanayiciler, bilim insanları ve üreticiler', ['Toprak sahibi soylular ile ordunun üst düzey komutanları', 'Kilise ve din adamları', 'Seçilmiş yargıçlar ve hukukçular'], 'Saint-Simon feodal ve askerî düzenin yerini üretime dayalı bir sanayi toplumunun alacağını, bu toplumu da sanayiciler ile bilim insanlarının yöneteceğini savundu.'),
  ('Belçikalı istatistikçi Adolphe Quetelet\'nin toplumsal olgulara uyguladığı ve bir toplumun ölçümlerinin ortalamasından türettiği kavram hangisidir?', 'Ortalama insan', ['İdeal tip', 'Genelleştirilmiş öteki', 'Kolektif bilinç'], 'Quetelet boy, kilo, evlilik ve suç gibi verilerin ortalamasından "ortalama insan" (l\'homme moyen) kavramını türetti. Toplumsal olguların istatistiksel düzenlilikler gösterdiğini savundu.'),
  ('Tocqueville\'e göre ABD\'de demokrasinin canlı kalmasında yurttaşların devlet dışında bir araya gelmesini sağlayan hangi oluşumlar önemli rol oynar?', 'Gönüllü dernekler ve yerel topluluklar', ['Kalıtsal soyluluk meclisleri', 'Merkezî ordu birlikleri', 'Lonca temelli zorunlu üretim birlikleri'], 'Tocqueville Amerika\'da yurttaşların sürekli dernekler kurduğunu, bu dernekleşmenin bireyciliğin ve merkezî gücün tehlikelerine karşı demokrasiyi koruduğunu gözlemledi.'),
  ('Comte\'un sosyolojinin ilkelerini ortaya koyduğu ve sosyoloji teriminin ilk kez geçtiği çok ciltli eseri hangisidir?', 'Pozitif Felsefe Dersleri', ['Sosyolojik Yöntemin Kuralları', 'Sosyolojinin İlkeleri', 'Toplumsal İşbölümü Üzerine'], 'Comte\'un 1830-1842 arasında altı cilt olarak yayımlanan "Pozitif Felsefe Dersleri" (Cours de philosophie positive) sosyoloji teriminin ilk kez geçtiği eserdir.'),
  ('Comte\'un bilimler hiyerarşisinde sosyolojiden hemen önce gelen ve sosyolojinin dayandığı bilim hangisidir?', 'Biyoloji', ['Kimya', 'Psikoloji', 'Astronomi'], 'Comte\'un sıralaması matematik, astronomi, fizik, kimya, biyoloji ve sosyolojidir. Psikolojiye bu sıralamada ayrı bir yer vermemiştir.'),
  ('Comte\'un yaşamının son döneminde, toplumsal birliği sağlamak için tanrı yerine insanlığın kendisini tapınma nesnesi yapan önerisi hangi adla bilinir?', 'İnsanlık dini', ['Doğa dini', 'Akıl kültü', 'Yurttaşlık ayini'], 'Comte "Pozitif Politika Sistemi"nde insanlığı "Büyük Varlık" olarak yücelten, rahipleri ve takvimi olan bir insanlık dini tasarladı.'),
  ('Comte\'un "Öngörmek için bilmek" ilkesi sosyolojiye hangi görevi yükler?', 'Toplumsal yasaları bilerek gelecekteki gelişmeleri önceden kestirmeyi', ['Geçmiş olayları yalnızca betimleyip yorumsuz bırakmayı', 'Bireylerin iç dünyasını sezgiyle kavramayı', 'Toplumsal olayları kutsal metinlere ve geleneksel otoritelere dayanarak açıklamayı'], 'Comte\'a göre bilimin amacı yasaları bulmak, yasaları bilmenin amacı da öngörüde bulunmak ve buna göre toplumu düzenlemektir.'),
  ('Comte\'a göre üç hal yasasındaki pozitif aşamaya ulaşmış bir bilim insanı, olayları açıklarken hangi soruyu esas alır?', 'Olaylar hangi değişmez ilişkilere göre gerçekleşiyor?', ['Olayların ilk ve son nedeni nedir?', 'Olayların ardındaki gizli doğaüstü güç ya da varlık hangisidir?', 'Olayların özünde hangi soyut ilke vardır?'], 'Pozitif aşamada mutlak nedenler ve özler aranmaz. Gözlemle ulaşılan olgular arasındaki değişmez ilişkiler, yani yasalar aranır.'),
  ('Comte\'un düşüncesinde ailenin önemine ilişkin yargı hangisidir?', 'Toplumun temel birimi bireyler değil ailelerdir', ['Aile, sanayi toplumunda tamamen ortadan kalkacaktır', 'Aile yalnızca ekonomik bir sözleşmedir', 'Toplumun temel birimi sınıflardır'], 'Comte toplumu bireylerin toplamı olarak görmez; toplumsal statik içinde aileyi toplumun temel birimi sayar.'),
  ('Comte\'un "Pozitif Felsefe Dersleri"ni kısaltarak İngilizceye çeviren ve sosyolojinin ilk kadın kuramcılarından sayılan yazar kimdir?', 'Harriet Martineau', ['Jane Addams', 'Beatrice Webb', 'Mary Wollstonecraft'], 'Harriet Martineau 1853\'te Comte\'un eserini özetleyerek İngilizceye kazandırdı. Comte eserin bu çevirisini çok beğenmiş ve Fransızcaya geri çevrilmesini desteklemiştir.'),
  ('Harriet Martineau, ABD\'de yaptığı gözlemlere dayanan "Amerika\'da Toplum" adlı eserinde özellikle hangi çelişkiyi eleştirmiştir?', 'Demokratik ilkelerle kölelik ve kadınların durumu arasındaki çelişkiyi', ['Sanayileşen kuzey eyaletleri ile tarıma dayalı güney eyaletleri arasındaki dengeyi', 'Katolik ve Protestan kiliseleri arasındaki rekabeti', 'Kıyı kentleriyle iç bölgeler arasındaki iklim farkını'], 'Martineau, eşitlik ilan eden Amerikan toplumunun köleliği sürdürmesini ve kadınları siyasal yaşamdan dışlamasını ahlaki ilkelerle uygulama arasındaki çelişki olarak inceledi.'),
  ('Spencer\'ın askerî toplumdan sanayi toplumuna geçişte öngördüğü değişim hangisidir?', 'Zorunlu işbirliğinden gönüllü işbirliğine geçilmesi', ['Gönüllü işbirliğinden zorunlu işbirliğine geçilmesi', 'Merkezî denetimin güçlenip bireyin geri planda kalması', 'Ticaretin gerileyip savaş ekonomisinin yaygınlaşması'], 'Spencer\'a göre askerî toplum merkezî denetime ve zorunlu işbirliğine, sanayi toplumu ise sözleşmeye ve gönüllü işbirliğine dayanır.'),
  ('Durkheim\'a göre toplumda işbölümünün gelişmesine yol açan temel etken hangisidir?', 'Nüfusun ve etkileşim yoğunluğunun artması', ['Bireylerin daha mutlu olmak istemesi', 'Dinsel inançların güçlenmesi', 'Devletin yasalarla meslekleri zorunlu olarak dağıtması'], 'Durkheim nüfus artışı ve insanların daha sık etkileşime girmesiyle yükselen "ahlaki (dinamik) yoğunluğun" rekabeti artırdığını, uzmanlaşmanın da bu rekabeti yumuşatan çözüm olduğunu savundu.'),
  ('Durkheim\'a göre bir toplumsal olgu açıklanırken onun işlevi ile ortaya çıkış nedeni hakkında hangi ilke geçerlidir?', 'İkisi ayrı ayrı araştırılmalıdır', ['İşlevi bilinince nedeni de bilinmiş olur', 'Yalnızca işlevi araştırılmalıdır', 'Yalnızca bireysel güdüler araştırılmalıdır'], 'Durkheim bir olgunun neye yaradığını göstermenin onun neden ortaya çıktığını açıklamadığını vurgular; bu nedenle neden ve işlev ayrı ayrı araştırılmalıdır.'),
  ('Durkheim\'ın "İntihar" çalışmasında ulaştığı bulgulardan biri hangisidir?', 'Protestanlarda intihar oranının Katoliklerden yüksek olması', ['Evlilerde intihar oranının bekârlardan yüksek olması', 'Savaş dönemlerinde intihar oranının belirgin biçimde artması', 'İntihar oranının yalnızca iklimle açıklanabilmesi'], 'Durkheim Protestanlığın bireyi daha yalnız bırakmasını, Katolikliğin ise daha güçlü bir topluluk bağı sunmasını bu farkla ilişkilendirdi. Evliler ve savaş dönemlerinde oranlar düşüktür.'),
  ('Bir ülkede iki şirket arasındaki sözleşme anlaşmazlığında mahkemenin cezadan çok zararın giderilmesine ve eski durumun sağlanmasına hükmetmesi, Durkheim\'a göre hangi hukuk türüne örnektir?', 'Onarıcı (iade edici) hukuk', ['Cezalandırıcı hukuk', 'Dinsel hukuk', 'Örfî hukuk'], 'Durkheim organik dayanışmanın egemen olduğu toplumlarda hukukun amacının suçluyu cezalandırmak değil, bozulan ilişkiyi eski haline getirmek olduğunu belirtti.'),
  ('Durkheim\'ın, dinsel törenlerde bir araya gelen topluluğun yaşadığı yoğun ortak heyecanı ve bireyin kendinden büyük bir güç hissetmesini anlatan kavramı hangisidir?', 'Kolektif coşku', ['Yabancılaşma', 'Karizmanın rutinleşmesi', 'Kolektif bilinçdışı'], 'Durkheim\'a göre tören sırasında yaşanan kolektif coşku, bireylere toplumun gücünü dinsel bir güç olarak hissettirir ve kutsal duygusunun kaynağı olur.'),
  ('Durkheim dini tanımlarken onu büyüden ayıran temel öğe olarak neyi gösterir?', 'İnananları ortak bir ahlaki toplulukta birleştirmesini', ['Doğaüstü varlıklara ve ruhlara ilişkin inançlar içermesini', 'Belirli sözcüklerin tekrarlanmasını', 'Bireysel çıkar sağlama amacını'], 'Durkheim\'a göre din, kutsal şeylere ilişkin inanç ve uygulamaların inananları "kilise" denen tek bir ahlaki toplulukta birleştirdiği sistemdir. Büyü ise kalıcı bir topluluk oluşturmaz.'),
  ('Durkheim\'ın "zorlanmış işbölümü" adını verdiği anormal durum hangisidir?', 'İnsanların yeteneklerine değil, eşitsiz koşullara göre işlere yerleştirilmesi', ['İşbölümünün hiç gelişmemiş olması', 'Herkesin aynı işi yapmaya zorlanması', 'Bütün mesleklerin devlet tarafından eşit biçimde ücretlendirilmesi ve atanması'], 'Durkheim\'a göre işbölümü kendiliğinden ve yeteneklere uygun işlediğinde dayanışma yaratır. Doğuştan eşitsizlikler insanları uygun olmayan işlere iterse işbölümü zorlanmış hale gelir ve çatışma doğurur.'),
  ('Durkheim\'ın en önemli öğrencilerinden biri olan ve aynı zamanda yeğeni olan antropolog-sosyolog kimdir?', 'Marcel Mauss', ['Maurice Halbwachs', 'Lucien Lévy-Bruhl', 'Claude Lévi-Strauss'], 'Marcel Mauss, Durkheim\'ın kız kardeşinin oğludur. L\'Année sociologique çevresinde çalıştı ve armağan üzerine ünlü çalışmasını yazdı.'),
  ('Durkheim\'ın, modern toplumda kolektif bilincin zayıflamasına karşın yükselen ve bireyin onurunu kutsal sayan anlayışı adlandırmak için kullandığı kavram hangisidir?', 'Birey kültü', ['Atalar kültü', 'Devlet kültü', 'Kahraman kültü'], 'Durkheim\'a göre modern toplumlarda ortak inançların içeriği azalırken bireyin onuruna ve haklarına duyulan saygı, birey kültü biçiminde kutsal bir değer haline gelir.'),
  ('Bir araştırmacı, intihar oranlarını açıklarken kişilerin psikolojik bunalımlarına değil, bölgeler arasındaki din, aile yapısı ve ekonomik değişim farklarına bakıyor. Bu tutum Durkheim\'ın hangi yaklaşımına uygundur?', 'Toplumsal olguları toplumsal nedenlerle açıklamaya', ['Olguları bireylerin eylemlerine yükledikleri öznel anlamlarla açıklamaya', 'Olguları biyolojik kalıtıma bağlamaya', 'Olguları yalnızca tarihsel kişiliklerle açıklamaya'], 'Durkheim intihar gibi en bireysel görünen bir davranışın oranlarının bile toplumsal bütünleşme ve düzenleme düzeyleriyle açıklanabileceğini gösterdi.'),
  ('Durkheim\'ın toplumsal olguları incelerken araştırmacıdan ilk olarak hangi tutumu beklediği söylenebilir?', 'Önceden edinilmiş kanılardan ve önyargılardan uzak durmayı', ['Olguyu kendi değer yargılarına göre sınıflandırmayı', 'Yalnızca kişisel deneyimine dayanmayı', 'Önce olgunun ahlaki açıdan iyi mi kötü mü olduğuna karar vermeyi'], 'Durkheim yöntem kurallarında araştırmacının gündelik önyargılardan (prenotions) sistemli biçimde kurtulması gerektiğini vurgular.'),
  ('Weber\'in "Bilim Meslek Olarak" konuşmasında üniversite öğretim üyelerine ilişkin savunduğu görüş hangisidir?', 'Kürsüden öğrencilere siyasi ve ahlaki değer yargıları aşılanmamalıdır', ['Öğretim üyesi derste öğrencilerine hangi partiyi seçmeleri gerektiğini göstermelidir', 'Bilim, yaşamın anlamı sorusuna kesin yanıt vermelidir', 'Akademisyen yalnızca devletin belirlediği değerleri öğretmelidir'], 'Weber bilimin olgular hakkında bilgi verebileceğini ama hangi değerlerin seçileceğine karar veremeyeceğini savunur; bu nedenle öğretim üyesinin kürsüyü propaganda için kullanmasına karşı çıkar.'),
  ('Weber\'in ölümünden sonra eşi Marianne Weber tarafından derlenerek yayımlanan ve otorite, bürokrasi, hukuk gibi konuları sistemli biçimde işleyen kapsamlı eseri hangisidir?', 'Ekonomi ve Toplum', ['Kapital', 'Toplumsal Sistem', 'Kitle ve İktidar'], '"Ekonomi ve Toplum" Weber\'in 1920\'de ölümünden sonra 1922\'de yayımlandı. Weber\'in sosyolojik kavramlarının en kapsamlı açıklaması bu eserdedir.'),
  ('Weber\'in Püritenler için kullandığı "dünya içi çilecilik" kavramı neyi anlatır?', 'Dünyadan kaçmadan, gündelik iş yaşamında disiplinli ve gösterişsiz yaşamayı', ['Manastıra çekilip gündelik yaşamdan ve dünyevi işlerden tümüyle uzaklaşmayı', 'Kazancı hemen lüks tüketime harcamayı', 'Çalışmayı reddedip yalnızca ibadetle yaşamayı'], 'Püriten çilecilik manastırda değil, meslek yaşamında gerçekleşir: çok çalışılır ama kazanç harcanmaz, birikir. Bu da sermaye birikimini kolaylaştırır.'),
  ('Weber\'e göre kapitalizmin ilk dönemlerinde dinsel kaynaklı olan disiplinli çalışma ahlakının, modern kapitalizm yerleştikten sonraki durumu nasıldır?', 'Dinsel temelinden kopmuş ama sistemin zorlayıcılığıyla sürmektedir', ['Dinsel temeli giderek güçlenmiştir', 'Tamamen ortadan kalkmış ve yerini aylaklığa bırakmıştır', 'Yalnızca Katolik ülkelerde ve kırsal kesimlerde varlığını sürdürmektedir'], 'Weber, Püritenin isteyerek çalıştığını, modern insanın ise çalışmak zorunda olduğunu söyler. Dinsel ruh kaybolmuş, geriye mekanik işleyen bir düzen kalmıştır.'),
  ('Weber, kapitalizmin doğuşunu Protestan ahlakıyla ilişkilendirirken ekonomik etkenlerin rolüne ilişkin hangi tutumu benimsemiştir?', 'Ekonomik etkenleri yadsımadan, kültürel etkenlerin de nedensel rolünü göstermeyi', ['Ekonomik etkenlerin kapitalizmin doğuşunda hiçbir rol oynamadığını kesin olarak kanıtlamayı', 'Tarihi yalnızca dinsel fikirlerle açıklamayı', 'Ekonominin tek belirleyici olduğunu kabul etmeyi'], 'Weber tek yanlı materyalist açıklamanın yerine tek yanlı idealist bir açıklama koymak istemediğini açıkça belirtir; çok nedenli bir açıklamayı savunur.'),
  ('Bir araştırmacı Weber\'in yöntemini izleyerek bürokrasiyi incelemek istiyor. Aşağıdaki çalışma adımlarından hangisi bu yönteme en uygundur?', 'Bürokrasinin belirgin özelliklerini abartan bir model kurup gerçek örgütleri onunla karşılaştırmak', ['Tek bir kurumu gözlemleyip bulguları tüm toplumlara genellemek', 'Bürokrasinin iyi mi kötü mü olduğuna önceden karar verip verileri yalnızca bu yargıya göre seçmek', 'Yalnızca bürokratların biyolojik özelliklerini ölçmek'], 'Weber\'in ideal tipi bir ölçme çubuğu gibi kullanılır: gerçeklikteki örnekler, saf modelden ne ölçüde saptığına bakılarak karşılaştırılır.'),
  ('Engels\'in Manchester\'daki gözlemlerine dayanarak 1845\'te yayımladığı ve sanayi işçilerinin konut, sağlık ve çalışma koşullarını belgeleyen eseri hangisidir?', 'İngiltere\'de İşçi Sınıfının Durumu', ['Ailenin, Özel Mülkiyetin ve Devletin Kökeni', 'Doğanın Diyalektiği', 'Ütopik Sosyalizmden Bilimsel Sosyalizme'], 'Engels, babasının Manchester\'daki fabrikasında çalışırken işçi mahallelerini gözlemledi. Eser, erken sanayi kentinin toplumsal sorunlarını ayrıntıyla betimler.'),
  ('Marx\'ın "Kapital" adlı eserinin birinci cildi hangi yılda yayımlanmıştır?', '1867', ['1848', '1883', '1859'], 'Kapital\'in birinci cildi 1867\'de yayımlandı. İkinci ve üçüncü ciltler Marx\'ın 1883\'teki ölümünden sonra Engels tarafından hazırlanıp yayımlandı.'),
  ('Marx ve Engels\'in "Alman İdeolojisi"nde dile getirdiği "Egemen sınıfın düşünceleri her çağda egemen düşüncelerdir" yargısının dayanağı hangisidir?', 'Maddi üretim araçlarını elinde tutan sınıfın düşünsel üretim araçlarını da denetlemesi', ['Düşüncelerin ekonomik yapıdan tümüyle bağımsız gelişmesi', 'Egemen sınıfın sayıca toplumun büyük çoğunluğunu oluşturması ve tüm seçimleri kazanması', 'Her bireyin doğuştan aynı düşüncelere sahip olması'], 'Marx ve Engels\'e göre maddi gücü elinde tutan sınıf, okul, basın ve din gibi düşünce üreten kurumları da etkiler; böylece kendi dünya görüşünü genel doğru olarak yayar.'),
  ('Marx\'ın sınıf çözümlemesinde dilenciler, serseriler ve suçlulardan oluşan, üretim sürecinin dışında kalan ve devrimci bir bilinç geliştirmesi beklenmeyen kesime verdiği ad hangisidir?', 'Lümpenproletarya', ['Küçük burjuvazi', 'Aristokrasi', 'Köylülük'], 'Marx lümpenproletaryayı örgütsüz, kararsız ve gerici güçlerce kolayca satın alınabilecek bir kesim olarak gördü.'),
  ('Marx\'a göre kapitalizmde sürekli işsiz ya da yarı işsiz bir kitlenin bulunması ücretleri nasıl etkiler ve bu kitleye ne ad verilir?', 'Ücretleri aşağı baskılar; yedek sanayi ordusu', ['Ücretleri yükseltir; işçi aristokrasisi', 'Ücretleri etkilemez; kendinde sınıf', 'Ücretleri yükseltir; lümpenproletarya'], 'Marx\'a göre işsizler ordusu, çalışan işçilerin pazarlık gücünü zayıflatır ve ücretlerin düşük kalmasına hizmet eder.'),
  ('Tarihsel materyalizme göre toplumların geçtiği üretim tarzları doğru sırayla hangi seçenekte verilmiştir?', 'İlkel komünal, köleci, feodal, kapitalist', ['Köleci, ilkel komünal, kapitalist, feodal', 'Feodal, köleci, ilkel komünal, kapitalist', 'İlkel komünal, feodal, köleci, kapitalist'], 'Marx ve Engels\'in şemasında ilkel komünal toplumu köleci toplum, onu feodal toplum, onu da kapitalist toplum izler. Kapitalizmden sonra sosyalizme geçileceği öngörülür.'),
  ('Bir fabrikadaki dokuma tezgâhları, enerji kaynakları ve işçilerin becerileri Marx\'ın kavramlarıyla hangi başlık altında yer alır?', 'Üretim güçleri', ['Üretim ilişkileri', 'Üstyapı', 'Sınıf bilinci'], 'Üretim güçleri, araçlar, teknoloji ve emek gücünden oluşur. Mülkiyet ve işçi-patron ilişkisi ise üretim ilişkileri başlığına girer.'),
  ('Marx\'a göre bir malın ihtiyacı karşılama yararı ile başka mallarla takas edilebilme oranı arasındaki ayrım hangi kavram çiftiyle anlatılır?', 'Kullanım değeri ve değişim değeri', ['Artı değer ve kâr', 'Altyapı ve üstyapı', 'Mutlak değer ve göreli değer'], 'Kullanım değeri malın somut yararını, değişim değeri ise piyasada başka mallarla değiştirilme oranını anlatır. Kapitalizmde üretim değişim değeri için yapılır.'),
  ('Marx\'ın tarihsel materyalizm anlayışını en iyi özetleyen yargı hangisidir?', 'İnsanların toplumsal varlığı, bilinçlerini belirler', ['İnsanların bilinci, toplumsal varlıklarını belirler', 'Tarihi yalnızca büyük kişilerin iradesi yönlendirir', 'Toplumsal değişme yalnızca coğrafyaya bağlıdır'], 'Marx "Ekonomi Politiğin Eleştirisine Katkı"nın önsözünde insanların bilincinin varlıklarını değil, toplumsal varlıklarının bilinçlerini belirlediğini yazar.'),
  ('Marx\'a göre kapitalizmden komünizme geçiş döneminde işçi sınıfının siyasal iktidarı elinde tutmasını anlatan kavram hangisidir?', 'Proletarya diktatörlüğü', ['Aydınlanmış despotizm', 'Yasal-ussal otorite', 'Karizmanın rutinleşmesi'], 'Marx "Gotha Programının Eleştirisi"nde kapitalist ve komünist toplum arasında bir devrimci dönüşüm dönemi ve buna karşılık gelen proletarya diktatörlüğü bulunduğunu yazar.'),
  ('Georg Simmel\'in "Yabancı" adlı denemesinde tanımladığı yabancı figürünün temel özelliği hangisidir?', 'Gruba hem yakın hem de uzak olması', ['Gruba hiç uğramayan bir gezgin olması', 'Grubun en eski ve en köklü üyesi olması', 'Grupla tümüyle düşmanca ilişki içinde olması'], 'Simmel\'e göre yabancı bugün gelip yarın gitmeyen, grubun içinde yaşayan ama ona tam ait olmayan kişidir. Bu yakınlık-uzaklık bileşimi ona nesnel bir bakış kazandırır.'),
  ('Simmel\'e göre topluluk içindekilerin, kendi aralarında söylemedikleri sırları bazen bir yabancıya açabilmelerinin nedeni hangisidir?', 'Yabancının grubun çıkar ve bağlarına karışmamış nesnel konumu', ['Yabancının grubun yasalarına göre yargılanıp cezalandırılabilmesi', 'Yabancının grubun dilini hiç bilmemesi', 'Yabancının grubun lideri olarak görülmesi'], 'Simmel, yabancının grubun yerleşik bağlılıklarından bağımsız olduğu için nesnel bir dinleyici ve yargıç gibi görüldüğünü, bu yüzden kendisine itiraflarda bulunulduğunu belirtir.'),
  ('Simmel\'in 1900\'de yayımlanan ve para ekonomisinin bireysel özgürlük, ilişkilerin nesnelleşmesi ve modern yaşam üzerindeki etkilerini inceleyen eseri hangisidir?', 'Paranın Felsefesi', ['Kapital', 'Ekonomi ve Toplum', 'Büyük Dönüşüm'], '"Paranın Felsefesi" paranın ilişkileri soyutlaştırıp hesaplanabilir kıldığını, bireye özgürlük sağlarken ilişkileri de kişisizleştirdiğini tartışır.'),
  ('Simmel\'e göre modern bireyin aile, meslek, din ve dernekler gibi birbirinden farklı birçok çevreye aynı anda üye olmasının sonucu hangisidir?', 'Her bireyin kendine özgü bir çevreler bileşimi taşıyarak bireyselleşmesi', ['Bireyin tek bir gruba tümüyle bağımlı hale gelip özgürlüğünü yitirmesi', 'Bütün bireylerin birbirine tıpatıp benzemesi', 'Toplumsal grupların ortadan kalkması'], 'Simmel\'in "toplumsal çevrelerin kesişmesi" düşüncesine göre çevrelerin kesişim noktası her bireyde farklıdır; bu da modern bireyselliğin kaynağıdır.'),
  ('Simmel\'in, büyük kentte yaşayanların zihinsel yaşamını ve para ekonomisiyle ilişkisini çözümlediği 1903 tarihli denemesinin adı hangisidir?', 'Metropol ve Zihinsel Yaşam', ['Bir Yaşam Biçimi Olarak Kentlileşme', 'Kentin Kültürü', 'Bahçe Kentler'], 'Simmel\'in 1903 tarihli "Metropol ve Zihinsel Yaşam" denemesi kent sosyolojisinin temel metinlerindendir. "Bir Yaşam Biçimi Olarak Kentlileşme" Wirth\'e, "Kentin Kültürü" Mumford\'a aittir.'),
  ('Tönnies\'e göre cemaat ilişkilerinin dayandığı irade türü hangisidir?', 'Doğal, içten gelen özsel irade', ['Hesaplı ve araçsal seçimsel irade', 'Yasalarla dayatılan devlet iradesi', 'Piyasanın kişisiz iradesi'], 'Tönnies cemaati duygu, alışkanlık ve gelenekten doğan özsel iradeye (Wesenwille), cemiyeti ise çıkar hesabına dayanan seçimsel iradeye (Kürwille) bağlar.'),
  ('Vilfredo Pareto, Machiavelli\'den esinlenerek yönetici seçkinleri hangi iki tipe ayırmıştır?', 'Tilkiler ve aslanlar', ['Kartallar ve güvercinler', 'Kurtlar ve kuzular', 'Arılar ve karıncalar'], 'Pareto kurnazlık ve ikna ile yöneten seçkinleri "tilki", güç ve kararlılıkla yöneten seçkinleri "aslan" olarak adlandırır.'),
  ('Pareto\'nun "Tarih bir aristokrasiler mezarlığıdır" sözü hangi düşünceyi dile getirir?', 'Hiçbir seçkin grubun iktidarda kalıcı olamayıp yerini başkasına bıraktığını', ['Tarihin yalnızca soyluların birbirleriyle yaptığı savaşlardan ibaret olduğunu', 'Aristokrasinin en adil yönetim biçimi olduğunu', 'Halkın hiçbir zaman yönetimde yer almadığını'], 'Pareto\'ya göre seçkinler zamanla yozlaşır ve yerlerini yeni seçkinlere bırakır; bu söz seçkinlerin dolaşımı düşüncesinin çarpıcı bir özetidir.'),
  ('Tarde ile Durkheim arasındaki ünlü tartışmanın özü hangisidir?', 'Toplumsal olguların taklitle mi, bireyi aşan bir gerçeklikle mi açıklanacağı', ['Sosyolojinin mi tarihin mi daha eski bir bilim olduğu', 'İstatistiksel verilerin sosyolojik araştırmalarda kullanılıp kullanılamayacağı', 'Dinin toplumda hiçbir işlevi olmadığı'], 'Tarde toplumsal yaşamı bireyler arası taklit zincirleriyle açıklarken, Durkheim toplumsal olguların bireylerin dışında ve üstünde bir gerçeklik olduğunu savundu.'),
  ('İbn Haldun\'un ünlü "Mukaddime"si aslında hangi büyük eserin giriş bölümüdür?', 'Kitabü\'l-İber', ['Siyasetname', 'Kutadgu Bilig', 'Mesnevi'], 'Mukaddime, İbn Haldun\'un evrensel tarih kitabı Kitabü\'l-İber\'in ilk cildi olarak yazılmış bir giriştir; sonradan bağımsız bir eser gibi okunmuştur.'),
  ('İbn Haldun\'un "Mağlup, galibe benzemeye meyleder" yargısı en iyi hangi gözlemle örneklenebilir?', 'Yenilen bir halkın giyim ve yaşam tarzında galip halkı taklit etmesi', ['Yenilen halkın kendi geleneklerine ve yaşam tarzına daha sıkı sarılması', 'Galip halkın yenilenin dilini benimsemesi', 'İki halkın da birbirinden tümüyle yalıtılması'], 'İbn Haldun, yenilen toplumun üstünlüğü galibin kusursuzluğuna bağladığını ve bu nedenle onun giyimini, silahlarını ve âdetlerini taklit ettiğini belirtir.'),
  ('İbn Haldun\'a göre asabiyetin en güçlü ve doğal kaynağı hangisidir?', 'Kan bağı ve soy birliği', ['Ortak ticari çıkar', 'Devletin çıkardığı yasalar', 'Aynı kentte doğmuş olmak'], 'İbn Haldun asabiyetin özünü akrabalık ve soy bağında görür; antlaşma ya da himaye yoluyla gruba katılanlar da zamanla bu bağın bir parçası gibi davranır.'),
  ('İbn Haldun\'un insanın toplum içinde yaşama zorunluluğunu anlatırken kullandığı "İnsan tabiatı gereği medenidir" ilkesinin gerekçesi hangisidir?', 'Bireyin beslenme ve korunma ihtiyaçlarını tek başına karşılayamaması', ['İnsanın doğuştan kalabalık kentlerde yaşamayı kırsal yaşama tercih etmesi', 'Toplumun tanrısal bir buyrukla kurulması', 'Her insanın yönetici olma isteği taşıması'], 'İbn Haldun\'a göre insan yiyeceğini üretmek ve kendini korumak için başkalarıyla işbirliği yapmak zorundadır; bu yüzden toplu yaşam (içtimâ) zorunludur.'),
  ('İbn Haldun\'a göre bir devletin kuruluş döneminde vergi oranları düşük ama toplam vergi geliri yüksektir; son dönemde ise oranlar artırıldığı halde gelir düşer. Bunun nedeni hangisidir?', 'Ağır vergilerin üretim ve ticaret isteğini kırması', ['Kuruluş döneminde nüfusun son döneme göre çok daha kalabalık olması', 'Son dönemde paranın tümüyle ortadan kalkması', 'Vergilerin yalnızca bedevilerden toplanması'], 'İbn Haldun yüksek vergilerin halkın çalışma ve kazanma isteğini azalttığını, ekonomik etkinlik daraldıkça toplam gelirin de düştüğünü gözlemler.'),
  ('İbn Haldun\'a göre servetin ve kazancın asıl kaynağı hangisidir?', 'İnsan emeği', ['Altın ve gümüş madenleri', 'Hükümdarın bağışları', 'Savaş ganimetleri'], 'İbn Haldun kazancın emeğin değeri olduğunu, el sanatlarının ve ticaretin de emek yoluyla değer yarattığını savunur.'),
  ('İbn Haldun\'a göre bedeviler hadarilere göre hangi bakımdan üstündür?', 'Cesaret ve ahlaki saflık bakımından', ['Bilim ve sanatta ilerlemişlik bakımından', 'Zenginlik ve lüks tüketim bakımından', 'Kalabalık nüfus bakımından'], 'İbn Haldun bedevilerin zorlu koşullarda yaşadığı için daha cesur ve kendine yeterli olduğunu, kentlilerin ise rahatlıkla gevşeyip korunmayı başkalarına bıraktığını belirtir.'),
  ('Ziya Gökalp\'in Türk toplumunun izleyeceği yolu üç ilkeyle özetlediği 1918 tarihli kitabı hangisidir?', 'Türkleşmek, İslamlaşmak, Muasırlaşmak', ['Türkiye Nasıl Kurtarılabilir?', 'Üç Tarz-ı Siyaset', 'Türk Töresinin Tarihi'], 'Gökalp bu eserinde millî kültüre (Türkleşme), dinî değerlere (İslamlaşma) ve Batı medeniyetinin tekniğine (Muasırlaşma) dayanan bir sentez önerdi. Üç Tarz-ı Siyaset Yusuf Akçura\'nındır.'),
  ('Ziya Gökalp\'e göre bir milleti oluşturan temel bağ hangisidir?', 'Aynı dil ve kültürü paylaşıp aynı terbiyeyi almış olmak', ['Aynı ırktan gelmek', 'Aynı coğrafi bölgede doğup aynı topraklarda yaşamış olmak', 'Aynı devlete vergi ödemek'], 'Gökalp milleti ırk ya da kan bağıyla değil; dilce, dince, ahlakça ve estetik bakımından ortak bir terbiye almış bireylerin topluluğu olarak tanımlar.'),
  ('Ziya Gökalp\'in toplumların gelişimine ilişkin evrimci şemasına göre toplumlar hangi sırayla ilerler?', 'Kavim, ümmet, millet', ['Millet, ümmet, kavim', 'Ümmet, kavim, millet', 'Kavim, millet, ümmet'], 'Gökalp\'e göre ilkel kavim toplumlarından dinî bağın belirleyici olduğu ümmet aşamasına, oradan da kültür birliğine dayanan millet aşamasına geçilir.'),
  ('Ziya Gökalp\'in Mondros Mütarekesi\'nin ardından İngilizlerce sürgün edildiği yer neresidir?', 'Malta', ['Kıbrıs', 'Rodos', 'Sakız'], 'Gökalp 1919\'da tutuklanarak diğer İttihatçı önderlerle birlikte Malta\'ya sürgün edildi ve 1921\'de serbest bırakıldı.'),
  ('Ziya Gökalp\'in hars-medeniyet ayrımına göre, Batı\'dan alınan bir sanayi tekniğinin Türk toplumuna aktarılması ve halk müziğinin korunması aynı anda nasıl değerlendirilir?', 'Medeniyetin alınıp harsın korunması', ['Harsın alınıp medeniyetin korunması', 'Hem harsın hem medeniyetin terk edilmesi', 'Yalnızca ümmet aşamasına dönülmesi'], 'Gökalp\'e göre teknik ve bilim uluslararası medeniyete aittir ve alınabilir; halk müziği gibi millî değerler ise harsa aittir ve korunmalıdır.'),
  ('Prens Sabahattin\'in 1906\'da kurduğu ve görüşlerini adında taşıyan örgüt hangisidir?', 'Teşebbüs-i Şahsi ve Adem-i Merkeziyet Cemiyeti', ['İttihat ve Terakki Cemiyeti', 'Türk Ocakları', 'Ahrar Fırkası'], 'Prens Sabahattin bireysel girişimi ve yerinden yönetimi savunan görüşlerini bu cemiyet aracılığıyla yaydı. Ahrar Fırkası onun görüşlerine yakın olsa da ayrı bir partidir.'),
  ('Prens Sabahattin\'in Osmanlı toplumunun sorunlarını ve çözüm önerilerini anlattığı ünlü eseri hangisidir?', 'Türkiye Nasıl Kurtarılabilir?', ['Türkçülüğün Esasları', 'Türkleşmek, İslamlaşmak, Muasırlaşmak', 'Hürriyet Kasidesi'], 'Prens Sabahattin bu eserinde toplumun cemaatçi yapısının bireysel girişimi engellediğini ve eğitimden başlayan bir dönüşüm gerektiğini savunur.'),
  ('Prens Sabahattin, toplumun bireyci bir yapıya kavuşması için en başta hangi alanda değişiklik yapılması gerektiğini savunmuştur?', 'Bireyi kendi ayakları üzerinde durmaya alıştıran bir eğitim sistemine', ['Ordunun yeniden örgütlenmesine', 'Merkezî yönetimin güçlendirilip taşradaki bütün yetkilerin İstanbul\'a toplanmasına', 'Dinî kurumların kapatılmasına'], 'Sabahattin\'e göre gençlere uygulamalı ve girişimci bir eğitim verilmeli, böylece bireyler devlete ve aileye bağımlı olmadan iş kurabilmelidir.'),
  ('Mübeccel Kıray\'ın Ereğli araştırmasında geliştirdiği "tampon mekanizma" kavramı neyi anlatır?', 'Hızlı değişmede eski ile yeni arasındaki geçişi yumuşatan ara kurumları', ['Kentlerde trafiği düzenlemek için kurulan yerel birimleri', 'Kırdan kente göçü tümüyle durdurmak amacıyla alınan sert devlet önlemlerini', 'Sanayi kuruluşlarının yönetim kurullarını'], 'Kıray\'a göre hızlı toplumsal değişme dönemlerinde ne tam geleneksel ne tam modern olan ara mekanizmalar ortaya çıkar ve toplumun çözülmeden değişime uyum sağlamasına yardım eder.'),
  ('Şerif Mardin\'in 2000\'li yıllarda kamuoyunda yaygın biçimde tartışılan ve bireyin çevresindeki topluluğun beklentilerine uyması yönündeki baskıyı anlatan kavramı hangisidir?', 'Mahalle baskısı', ['Merkez-çevre gerilimi', 'Tampon mekanizma', 'Kültürel gecikme'], 'Mardin mahalle baskısı kavramıyla, resmî kurallardan değil yakın çevrenin bakışından ve yaptırımlarından kaynaklanan toplumsal denetimi anlattı.'),
  ('Mümtaz Turhan\'ın Batılılaşma sürecini kültür değişmesi kuramları ışığında tartıştığı eserlerinden biri hangisidir?', 'Garplılaşmanın Neresindeyiz?', ['Türkiye Nasıl Kurtarılabilir?', 'Modern Mahrem', 'Din ve İdeoloji'], 'Mümtaz Turhan "Kültür Değişmeleri" ve "Garplılaşmanın Neresindeyiz?" adlı eserlerinde Batılılaşmanın biçimsel taklitle değil, bilim ve tekniğin özümsenmesiyle başarılabileceğini savundu.'),
  ('Kemal Karpat\'ın kırdan kente göç ve kentlerdeki kendiliğinden yerleşim alanları üzerine yaptığı İstanbul merkezli araştırmasının konusu hangisidir?', 'Gecekondu', ['Göçebe aşiretler', 'Osmanlı loncaları', 'Kıyı balıkçı köyleri'], 'Karpat\'ın "Gecekondu: Kırsal Göç ve Kentleşme" adlı çalışması, gecekonduda yaşayanların kentle bütünleşme süreçlerini inceleyen öncü bir eserdir.'),
  ('Behice Boran\'ın akademik kariyerinin yanı sıra 1970\'lerde genel başkanlığını yaptığı siyasi parti hangisidir?', 'Türkiye İşçi Partisi', ['Demokrat Parti', 'Cumhuriyet Halk Partisi', 'Millî Nizam Partisi'], 'Behice Boran 1975\'ten ölümüne kadar Türkiye İşçi Partisi\'nin genel başkanlığını yürüttü; Türkiye\'de bir siyasi partinin başına geçen ilk kadınlardan biridir.'),
  ('Şerif Mardin\'in merkez-çevre modelinde Osmanlı\'dan devralınan "merkez" kavramı en çok hangi kesimi anlatır?', 'Devleti ve onunla bütünleşmiş askerî-bürokratik seçkinleri', ['Anadolu\'daki köylüleri ve taşra eşrafını', 'Yalnızca İstanbul\'daki tüccarları', 'Dinî tarikatları, medrese çevresini ve taşradaki ulema sınıfını'], 'Mardin\'e göre Osmanlı\'da merkez, devlet ve bürokrasi etrafında örgütlenmiş seçkinlerden oluşur; taşra, köylüler ve yerel güçler ise çevreyi oluşturur.'),
  ('W. I. Thomas ile Florian Znaniecki\'nin "Avrupa ve Amerika\'da Polonyalı Köylü" adlı çalışmasında başlıca veri kaynağı olarak kullandıkları malzeme hangisidir?', 'Göçmenlerin mektupları ve yaşam öyküleri gibi kişisel belgeler', ['Ulusal nüfus sayımının sonuçları', 'Laboratuvar deneylerinin ölçümleri', 'Telefonla ve postayla yapılan büyük ölçekli kamuoyu yoklamaları'], 'Bu çalışma Polonya\'daki aileler ile ABD\'ye göç edenler arasındaki mektuplara ve bir göçmenin uzun yaşam öyküsüne dayanır; kişisel belgelerin sosyolojide kullanımının klasik örneğidir.'),
  ('Chicago Okulu\'nun kentleri incelerken bitki ekolojisinden ödünç aldığı ve bir mahallenin yeni gelen bir grup tarafından giderek ele geçirilmesini anlatan kavram çifti hangisidir?', 'İstila ve ardıllık', ['Altyapı ve üstyapı', 'Ön sahne ve kulis', 'Cemaat ve cemiyet'], 'İnsan ekolojisi yaklaşımı, bitki türlerinin bir alanı ele geçirmesine benzer biçimde yeni grupların mahallelere yerleştiğini ve eski sakinlerin yerini aldığını istila ve ardıllık kavramlarıyla açıklar.'),
  ('Clifford Shaw ve Henry McKay\'in Chicago\'da yaptığı araştırmalarda, mahalledeki etnik gruplar değiştiği halde suç oranlarının yüksek kalmaya devam etmesi hangi sonuca götürmüştür?', 'Suçun grupların özelliğinden çok mahallenin toplumsal çözülmesinden doğduğu', ['Suçun kalıtsal olarak aktarıldığı', 'Suçun yalnızca belirli etnik gruplara özgü olduğu', 'Mahallelerin suç oranlarıyla hiçbir ilgisi olmadığı'], 'Shaw ve McKay\'in toplumsal çözülme kuramına göre yoksulluk, nüfus devinimi ve zayıf toplumsal denetim, orada kim yaşarsa yaşasın suçu besler.'),
  ('George Herbert Mead\'in temel eseri sayılan "Zihin, Benlik ve Toplum" nasıl ortaya çıkmıştır?', 'Ölümünden sonra öğrencilerinin ders notlarından derlenerek', ['Mead\'in sağlığında kendi eliyle yazıp yayımladığı tek kitap olarak', 'Bir romanın içine gömülmüş denemeler olarak', 'Mead ile Durkheim\'ın ortak eseri olarak'], 'Mead yaşamı boyunca kitap yayımlamadı; "Zihin, Benlik ve Toplum" 1934\'te, ölümünden sonra öğrencilerinin tuttuğu ders notlarından derlendi.'),
  ('Mead\'e göre insan etkileşimini hayvanların hareketle iletişiminden ayıran temel özellik hangisidir?', 'Gönderen ve alan için aynı anlamı taşıyan simgelerin kullanılması', ['Seslerin hayvanlarınkinden daha yüksek perdeden ve uzun süre çıkarılması', 'Yalnızca içgüdüsel tepkilere dayanması', 'Bedensel hareketlerin hiç kullanılmaması'], 'Mead\'e göre dil gibi anlamlı simgeler, kişinin kendi davranışının başkasında uyandıracağı tepkiyi önceden kestirmesine olanak verir; bu da benliğin ve zihnin gelişiminin temelidir.'),
  ('Blumer\'in sembolik etkileşimciliğin temel önermelerinden biri hangisidir?', 'İnsanlar nesnelere, o nesnelerin kendileri için taşıdığı anlamlara göre davranır', ['İnsan davranışı yalnızca ekonomik yapı tarafından belirlenir', 'Toplumsal yapılar bireylerin yorumlarından tümüyle bağımsız ve mekanik biçimde işler', 'Anlamlar doğuştan gelir ve değişmez'], 'Blumer\'e göre anlamlar toplumsal etkileşimden doğar ve bireylerin yorumlama süreciyle sürekli yeniden işlenir; davranış bu anlamlara göre biçimlenir.'),
  ('Atlıkarıncaya binen on iki yaşındaki bir çocuğun, binişi küçümser tavırlarla bunun çocuk işi olduğunu belli etmeye çalışması Goffman\'ın hangi kavramına örnektir?', 'Rol mesafesi', ['Rol çatışması', 'Rol kümesi', 'Rol gerilimi'], 'Goffman rol mesafesini, kişinin üstlendiği role kendini tümüyle kaptırmadığını, o rolden biraz uzak durduğunu başkalarına göstermesi olarak tanımlar.'),
  ('Garfinkel\'in öğrencilerinden kendi evlerinde kiracı gibi aşırı kibar davranmalarını isteyerek gündelik yaşamın örtük kurallarını görünür kıldığı çalışmalarına ne ad verilir?', 'Bozma deneyleri', ['Hawthorne deneyleri', 'Gizli gözlem deneyleri', 'Kör deneyler'], 'Garfinkel\'in bozma (ihlal) deneyleri, olağan beklentiler çiğnendiğinde insanların şaşkınlık ve öfke gösterdiğini; böylece gündelik düzeni kuran sessiz kuralların varlığını ortaya koydu.'),
  ('Alfred Schutz\'un fenomenolojik sosyolojisi hangi iki düşünürün görüşlerini birleştirme çabası olarak bilinir?', 'Husserl ve Weber', ['Marx ile Friedrich Engels', 'Comte ve Spencer', 'Hegel ve Tönnies'], 'Schutz, Husserl\'in fenomenolojisini Weber\'in anlayıcı sosyolojisiyle birleştirerek öznel anlamın gündelik yaşamda nasıl kurulduğunu inceledi.'),
  ('Schutz\'a göre insanların gündelik yaşamda karşılaştıkları kişi ve durumları "postacı", "öğretmen" gibi kalıp bilgilerle kavramasına ne ad verilir?', 'Tipleştirme', ['Yabancılaşma', 'Rasyonelleşme', 'Farklılaşma'], 'Schutz\'a göre gündelik bilgi stokumuz tipleştirmelerden oluşur. Postacıyı kişisel olarak tanımasak da onun ne yapacağını bu tip bilgisiyle öngörürüz.'),
  ('Berger ve Luckmann\'a göre toplumun insan ürünü olup bireyin karşısına nesnel bir gerçeklik olarak dikilmesi ve sonra bireyin onu benimsemesi hangi üç anlık süreçle açıklanır?', 'Dışsallaştırma, nesnelleşme, içselleştirme', ['Teolojik, metafizik, pozitif', 'Tez, antitez, sentez', 'Temas, rekabet, uzlaşma, asimilasyon'], 'İnsanlar dünyayı etkinlikleriyle üretir (dışsallaştırma), bu ürün bağımsız bir gerçeklik gibi görünür (nesnelleşme) ve toplumsallaşmayla bireyin bilincine geri yerleşir (içselleştirme).'),
  ('Berger ve Luckmann\'a göre kurumsallaşma nasıl ortaya çıkar?', 'Alışkanlığa dönüşmüş eylemlerin karşılıklı olarak tipleştirilmesiyle', ['Devletin her kurumu ayrı bir yasayla ve bir anda yukarıdan kurmasıyla', 'Bireylerin doğuştan getirdiği içgüdülerle', 'Yalnızca dinsel vahiy yoluyla'], 'Berger ve Luckmann\'a göre tekrarlanan eylemler alışkanlığa dönüşür; bu alışkanlıklar taraflarca ortaklaşa tipleştirildiğinde kurum doğar ve sonraki kuşaklara hazır bir gerçeklik olarak aktarılır.'),
  ('Peter Berger\'in 1963 tarihli "Sosyolojiye Çağrı" adlı eserinde sosyolojik bakışın ilk bilgeliği olarak gösterdiği ilke hangisidir?', 'Şeylerin göründükleri gibi olmadığı', ['Toplumun yalnızca bireylerin toplamı olduğu', 'Bütün toplumsal olayların ekonomiden kaynaklandığı', 'Sosyolojinin kesin yasalar bulabileceği'], 'Berger sosyolojik bilinci, resmî ve görünen açıklamaların arkasına bakmak, gündelik yaşamın sorgulanmayan varsayımlarını açığa çıkarmak olarak tanımlar.'),
  ('Talcott Parsons\'ın Marshall, Pareto, Durkheim ve Weber\'in görüşlerini birleştirerek "iradeci eylem kuramı"nı ortaya koyduğu 1937 tarihli eseri hangisidir?', 'Toplumsal Eylemin Yapısı', ['Toplumsal Sistem', 'Toplum Kuramı ve Toplumsal Yapı', 'Toplumsal İşbölümü Üzerine ve Dayanışma'], 'Parsons ilk büyük eserinde dört düşünürün, birbirinden bağımsız olarak aynı eylem kuramına yöneldiğini savundu. "Toplumsal Sistem" ise 1951 tarihlidir.'),
  ('Parsons\'ın kuramsal çalışmalarının çıkış noktası olarak benimsediği ve Hobbes\'tan esinlenen temel soru hangisidir?', 'Bireyler çıkarlarının peşindeyken toplumsal düzen nasıl mümkün olur?', ['Üretim araçlarının mülkiyeti kime aittir?', 'Kentler merkezden dışa doğru nasıl büyür?', 'Bireyler gündelik yaşamda benliklerini başkalarına nasıl sunar ve korur?'], '"Hobbesçu düzen sorunu" olarak bilinen bu soruya Parsons, ortak değer ve normların içselleştirilmesiyle yanıt verdi.'),
  ('Max Weber\'in "Protestan Ahlakı ve Kapitalizmin Ruhu" adlı eserini 1930\'da İngilizceye çeviren Amerikalı sosyolog kimdir?', 'Talcott Parsons', ['Robert K. Merton', 'C. Wright Mills', 'Herbert Blumer'], 'Heidelberg\'de doktora yapan Parsons, Weber\'i İngilizce konuşan dünyaya tanıtan ilk isimlerden oldu ve Protestan Ahlakı\'nı İngilizceye çevirdi.'),
  ('Robert K. Merton\'un, sosyolojinin ya tümüyle betimsel çalışmalarla ya da her şeyi açıklamaya çalışan büyük kuramlarla yetinmemesi gerektiğini savunarak önerdiği kuram türü hangisidir?', 'Orta erimli kuramlar', ['Büyük anlatılar', 'Evrimci aşama kuramları', 'Ütopik toplum kuramları'], 'Merton, Parsons\'ın soyut büyük kuramına karşı, sınırlı olgu alanlarına uygulanabilen ve görgül olarak sınanabilen orta erimli kuramları savundu. Referans grubu kuramı buna örnektir.'),
  ('Bir stajyer avukatın, henüz katılmadığı kıdemli avukatlar grubunun giyimini ve konuşma tarzını önceden benimsemeye başlaması Merton\'un hangi kavramıyla açıklanır?', 'Beklenen toplumsallaşma', ['Birincil toplumsallaşma', 'Yeniden toplumsallaşma', 'Ters yönlü (geriye dönük) toplumsallaşma'], 'Merton\'a göre bireyler girmeyi umdukları grubun değer ve davranışlarını önceden benimser. Bu, gruba geçişi kolaylaştırır ama mevcut grupla bağları zayıflatabilir.'),
  ('Merton\'un, tanınmış bilim insanlarının benzer katkılar için daha az tanınan meslektaşlarından çok daha fazla itibar görmesini anlatmak için İncil\'den esinlenerek kullandığı kavram hangisidir?', 'Matta (Matthew) etkisi', ['Hawthorne (gözlemlenme) etkisi', 'Pygmalion etkisi', 'Kelebek etkisi'], 'Merton bu kavramı "Kimde varsa ona daha çok verilecek" ayetinden aldı. Ünlü bilim insanları ortak çalışmalarda ve eş zamanlı buluşlarda orantısız biçimde öne çıkar.'),
  ('Merton\'un bilim normlarından "örgütlü kuşkuculuk" ilkesine en uygun davranış hangisidir?', 'Bir bulgunun, ünlü bir bilim insanından gelse de sınanmadan kabul edilmemesi', ['Araştırma sonuçlarının kâr amacıyla gizli tutulması', 'Bilim insanının kendi kuramını eleştirilere kapatması', 'Bulguların yalnızca aynı ülkedeki ve aynı kurumdaki bilim insanlarıyla paylaşılması'], 'Merton\'a göre bilim, bütün iddiaların görgül ve mantıksal ölçütlerle sistemli biçimde sorgulanmasını gerektirir. Sonuçların gizlenmesi ise ortaklaşacılık normunu çiğner.'),
  ('Merton\'un başlıca kuramsal makalelerini topladığı ve açık-örtük işlev ile anomi kuramını içeren 1949 tarihli eseri hangisidir?', 'Toplum Kuramı ve Toplumsal Yapı', ['Toplumsal Eylemin Yapısı', 'Sosyolojik Hayal Gücü ve Toplum', 'Toplumsal Çatışmanın İşlevleri'], '"Social Theory and Social Structure" Merton\'un işlevsel çözümleme paradigmasını, anomi kuramını ve bilim sosyolojisi yazılarını bir araya getirir.'),
  ('Merton\'un geleneksel işlevselcilikte eleştirdiği varsayımlardan biri hangisidir?', 'Toplumdaki her öğenin mutlaka olumlu bir işlev gördüğü', ['Toplumsal olguların başka toplumsal olgularla gözlemlenip karşılaştırılabileceği', 'Kurumların birbirini etkileyebileceği', 'Toplumların zamanla değişebileceği'], 'Merton işlevsel birlik, evrensel işlevselcilik ve vazgeçilmezlik varsayımlarını eleştirdi; bazı öğelerin işlevsiz ya da işlev bozucu olabileceğini vurguladı.'),
  ('Merton\'un sosyolojiye kazandırdığı "serendipity" kavramı araştırma sürecinde neyi anlatır?', 'Beklenmedik ve aranmayan bir bulgunun yeni bir kurama yol açması', ['Araştırmacının verileri bilinçli olarak kendi kuramının lehine çarpıtması', 'Bir kuramın hiçbir zaman sınanamaması', 'Aynı araştırmanın farklı yerlerde tekrarlanması'], 'Merton, araştırmada rastlantıyla ortaya çıkan, beklenmedik ve aykırı bir verinin yeni bir kuramın geliştirilmesini tetikleyebileceğini "serendipity" kavramıyla anlattı.'),
  ('Lewis Coser\'in Simmel\'in görüşlerinden yola çıkarak çatışmanın grup sınırlarını belirleme ve bütünleşmeyi güçlendirme gibi olumlu sonuçlarını incelediği eseri hangisidir?', 'Toplumsal Çatışmanın İşlevleri', ['Güç Seçkinleri ve Toplum', 'Sınıf Çatışması ve Sanayi Toplumu', 'Toplumsal Eylemin Yapısı'], 'Coser 1956\'da yayımlanan bu eserinde çatışmayı yalnızca yıkıcı bir olgu olarak değil, toplumsal sistemi uyarlayan ve bütünleştiren bir süreç olarak ele aldı.'),
  ('Ralf Dahrendorf\'a göre modern sanayi toplumlarında sınıf çatışmasının temel kaynağı hangisidir?', 'Örgütlerde otoritenin eşitsiz dağılımı', ['Üretim araçlarının özel mülkiyette toplanması', 'Dinsel inançların farklılığı', 'Bölgeler arası iklim farkları'], 'Dahrendorf, mülkiyet ile yönetimin ayrıştığı modern şirketlerde belirleyici olanın kimin emir verip kimin uyduğu olduğunu, yani otorite ilişkilerini öne çıkardı.'),
  ('Dahrendorf\'un yapısal işlevselciliği eleştirdiği "Ütopyadan Çıkış" makalesinde bu kuramı ütopyalara benzetmesinin nedeni hangisidir?', 'Değişmeyen, uyumlu ve çatışmasız bir toplum varsayması', ['Gelecekteki komünist toplumu betimlemesi', 'Bireylerin özgür iradesini abartması', 'Toplumsal değişmeyi yalnızca çatışmayla açıklaması'], 'Dahrendorf, işlevselciliğin tıpkı ütopyalar gibi değer uzlaşmasına dayanan, durağan ve dengeli bir toplum resmi çizdiğini ve değişmeyi açıklayamadığını ileri sürdü.'),
  ('Randall Collins\'in "Diploma Toplumu" adlı eserinde eğitim düzeyinin sürekli yükselmesini açıklarken öne sürdüğü görüş hangisidir?', 'Diplomaların iş becerisinden çok statü gruplarının kapanma aracı olması', ['Teknolojinin gerektirdiği bilginin her yıl ikiye katlanması', 'Gençlerin okula gitmekten başka seçeneğinin olmaması', 'Okulların yalnızca dinsel eğitim vermesi'], 'Collins, Weberci bir bakışla, artan diploma isteğinin iş gereklerinden çok grupların ayrıcalıklı mesleklere girişi sınırlama çabasından kaynaklandığını savundu.'),
  ('Birincil sapma ve ikincil sapma kavramlarını sosyolojiye kazandıran sosyolog kimdir?', 'Edwin Lemert', ['Edwin Sutherland', 'Travis Hirschi', 'Albert Cohen'], 'Lemert, ilk sapmanın çoğu zaman geçici olduğunu; toplumun tepkisi ve etiketleme sonucunda bireyin sapkın kimliği benimsemesiyle ikincil sapmanın ortaya çıktığını gösterdi.'),
  ('Albert Cohen\'e göre alt sınıftan gelen bazı erkek gençlerin okulda orta sınıf ölçütlerine göre başarısız sayılması sonucunda ortaya çıkan durum hangisidir?', 'Statü hüsranı ve değerleri tersine çeviren bir alt kültür', ['Okulda en yüksek notları alma yarışı', 'Orta sınıf değerlerini tümüyle benimseme', 'Ailelerin çocuklarını başka şehre göndermesi'], 'Cohen, "Suçlu Çocuklar" adlı eserinde statü kazanamayan gençlerin orta sınıf değerlerini tersine çeviren ve kendi aralarında saygınlık sağlayan bir alt kültür kurduğunu savundu.'),
  ('George Homans\'ın toplumsal değişim kuramını kurarken davranışçı psikolojiden ödünç aldığı önermelerden biri hangisidir?', 'Bir eylem ne kadar sık ödüllendirilirse o kadar sık tekrarlanır', ['Toplumsal olgular yalnızca başka toplumsal olgularla açıklanabilir', 'Bireyin bilinci toplumsal varlığını belirler', 'Kurumlar her zaman açık ve örtük işlevlere sahiptir'], 'Homans, Skinner\'ın davranışçılığından yararlanarak toplumsal davranışı ödül ve maliyet kavramlarıyla açıkladı; başarı önermesi bunlardan biridir.'),
  ('Peter Blau\'ya göre değişim ilişkilerinde güç nasıl ortaya çıkar?', 'Bir taraf karşılık olarak eşdeğer bir şey sunamadığında', ['Tarafların birbirine sundukları şeyler tam olarak eşit değerde olduğunda', 'Değişim tümüyle ortadan kalktığında', 'Tarafların aynı toplumsal sınıftan gelmesiyle'], 'Blau\'ya göre karşılığını ödeyemeyen taraf, yükümlülüğünü itaat ederek öder; böylece dengesiz değişimden güç ilişkisi doğar.'),
  ('Horkheimer\'ın 1937 tarihli makalesinde "geleneksel kuram" ile "eleştirel kuram"ı ayırırken eleştirel kurama yüklediği amaç hangisidir?', 'Toplumu betimlemekle kalmayıp insanın tahakkümden kurtuluşuna katkı sunmak', ['Toplumu doğa bilimlerindeki gibi tarafsızca ölçüp sınıflandırmak ve yasalarını bulmak', 'Var olan düzeni olduğu gibi meşrulaştırmak', 'Yalnızca bireysel ruh hallerini incelemek'], 'Horkheimer\'a göre geleneksel kuram mevcut düzeni veri kabul ederken eleştirel kuram, toplumsal koşulları değiştirmeyi ve özgürleşmeyi hedefler.'),
  ('Erich Fromm\'un 1941 tarihli "Özgürlükten Kaçış" adlı eserinde açıklamaya çalıştığı olgu hangisidir?', 'Kopuk ve yalnız kalan modern bireyin otoriter yönetimlere sığınması', ['Köylülerin topluca kentlere göç etmesinin ardındaki ekonomik ve demografik nedenler', 'Ortaçağ\'da manastır yaşamının yaygınlaşması', 'Çocukların dil edinme süreci'], 'Fromm, modern bireyin kazandığı özgürlüğün getirdiği yalnızlık ve güvensizlikten kaçmak için otoriteye boyun eğebileceğini; faşizmin kitlesel desteğini bununla açıkladı.'),
  ('Walter Benjamin\'in "Teknik Olarak Yeniden Üretilebilirlik Çağında Sanat Eseri" denemesine göre fotoğraf ve sinema gibi tekniklerle sanat eserinin yitirdiği nitelik hangisidir?', 'Biricikliğinden gelen aura', ['Ticari değeri', 'Seyirciye ulaşabilme ve yayılabilme gücü', 'Siyasal etkisi'], 'Benjamin\'e göre eserin "şimdi ve burada"lığından, tekliğinden kaynaklanan aurası çoğaltmayla söner; buna karşılık sanat geniş kitlelere ulaşma ve siyasallaşma olanağı kazanır.'),
  ('Habermas\'a göre 20. yüzyılda kamusal alanın gerilemesinin başlıca nedeni hangisidir?', 'Kitle iletişiminin ticarileşip tartışmanın yerini tüketimin alması', ['Gazetelerin yayın hayatına başlaması', 'Okuma yazma oranının düşmesi', 'Kahvehanelerin ve salonların sayısının aşırı artıp denetlenemez hale gelmesi'], 'Habermas, eleştirel tartışmanın yerini reklam, eğlence ve yönlendirilmiş kamuoyunun aldığını; yurttaşların tartışan bir kamudan tüketen bir kitleye dönüştüğünü savundu.'),
  ('Habermas\'ın "İletişimsel Eylem Kuramı"nda yaşam dünyasının sömürgeleştirilmesi kavramı neyi anlatır?', 'Para ve iktidarla işleyen sistemin anlaşmaya dayalı gündelik alanları işgal etmesini', ['Avrupalı devletlerin 19. yüzyılda Afrika ve Asya\'da sömürge imparatorlukları kurmasını', 'Kırsal alanların kentler tarafından yutulmasını', 'Dinsel kurumların devleti ele geçirmesini'], 'Habermas toplumu yaşam dünyası ve sistem olarak ayırır. Ekonomi ve bürokrasinin araçsal mantığı aile, eğitim ve kamusal tartışma gibi alanlara yayıldığında yaşam dünyası sömürgeleştirilir.'),
  ('Habermas\'ın, katılımcıların baskı altında olmadan eşit koşullarda konuştuğu ve yalnızca daha iyi argümanın gücünün geçerli olduğu kuramsal ölçüt için kullandığı kavram hangisidir?', 'İdeal konuşma durumu', ['Kolektif coşku', 'Toplumsal sözleşme', 'Sivil kayıtsızlık ritüeli'], 'Habermas\'a göre ideal konuşma durumu, gerçek tartışmaların ne ölçüde çarpıtıldığını değerlendirmek için kullanılan normatif bir ölçüttür.'),
  ('Habermas\'ın Postmodern düşünürlere karşı modernlik hakkında savunduğu görüş hangisidir?', 'Modernliğin terk edilmesi değil, tamamlanması gerektiği', ['Modernliğin tümüyle başarısız olup sona erdiği', 'Modernliğin yalnızca teknik bir gelişme olduğu', 'Aklın her türlü özgürleşme iddiasının terk edilmesi gerektiği'], 'Habermas, Aydınlanma\'nın akıl ve özgürleşme idealinin çarpıtıldığını ama değerini yitirmediğini; bu nedenle modernliğin tamamlanmayı bekleyen bir proje olduğunu savundu.'),
  ('Antonio Gramsci\'nin, belirli bir sınıfın içinden çıkıp o sınıfın dünya görüşünü örgütleyen ve yayan düşünürler için kullandığı kavram hangisidir?', 'Organik aydın', ['Geleneksel aydın', 'Serbestçe yüzen aydın', 'Kamusal aydın'], 'Gramsci, din adamları gibi kendini sınıflar üstü sayan geleneksel aydınlardan farklı olarak her sınıfın kendi organik aydınlarını yetiştirdiğini ve hegemonya mücadelesinde onların rolünün belirleyici olduğunu vurguladı.'),
  ('Pierre Bourdieu\'nün müzik, yemek ve giyim gibi alanlardaki beğenilerin toplumsal sınıfla ilişkisini büyük ölçekli anketlerle incelediği 1979 tarihli eseri hangisidir?', 'Ayrım', ['Aylak Sınıfın Teorisi', 'Yalnız Kalabalık', 'Tüketim Toplumu'], 'Bourdieu "Ayrım"da beğeninin doğal ya da kişisel değil, sınıfsal konumla biçimlenen ve sınıflar arası sınırları yeniden üreten bir ölçüt olduğunu gösterdi.'),
  ('Bourdieu\'ye göre işçi sınıfı ailelerinin doyurucu ve bol yemekleri, pratik ve dayanıklı eşyaları tercih etmesi hangi beğeni türüyle açıklanır?', 'Zorunluluk beğenisi', ['Özgürlük (lüks) beğenisi', 'Saf estetik beğeni', 'Avangart beğeni'], 'Bourdieu, kısıtlı kaynaklarla yaşayan sınıfların beğenisini işlevselliği öne çıkaran zorunluluk beğenisi; üst sınıflarınkini ise biçimi işleve üstün tutan özgürlük beğenisi olarak niteler.'),
  ('Michel Foucault\'nun "Hapishanenin Doğuşu" (Gözetlemek ve Cezalandırmak) adlı eserine göre 18. yüzyıl sonlarından itibaren cezalandırmada ne değişmiştir?', 'Bedene yönelik gösterişli işkenceden davranışı biçimlendiren disipline geçilmiştir', ['Hapis cezası tümüyle kaldırılıp yerini sürgüne bırakmıştır', 'Cezalar halka açık meydanlarda daha sık, daha kalabalık ve daha gösterişli uygulanmaya başlanmıştır', 'Cezalandırma yetkisi devletten kiliseye geçmiştir'], 'Foucault eserine 1757\'deki bir halka açık idamla başlar ve kısa sürede bunun yerini zaman çizelgeleri, gözetim ve düzeltmeye dayalı hapishane düzeninin aldığını gösterir.'),
  ('Foucault\'ya göre okullarda ve hastanelerde uygulanan sınav ve muayene neden güçlü bir disiplin tekniğidir?', 'Gözetim ile normalleştirici yargıyı birleştirip bireyi ölçülebilir bir vaka yapması', ['Bireyleri gözetimden tümüyle kurtarması', 'Yalnızca bilgi aktarmaya yarayıp iktidar ilişkileriyle ve sıralamayla hiçbir ilgisi olmaması', 'Herkese aynı notu verip farkları ortadan kaldırması'], 'Foucault\'ya göre sınav bireyleri görünür kılar, belgeler, karşılaştırır ve bir normdan sapmalarına göre sıralar; böylece bilgi ve iktidar birlikte işler.'),
  ('Giddens\'ın modernliği, sürücüsü bulunan ama tam denetlenemeyen ve önündekileri ezip geçebilen dev bir araca benzetmesinin anlamı hangisidir?', 'Modernliğin büyük olanaklar sunarken öngörülemez riskler de taşıması', ['Modernliğin tümüyle insan denetiminde ilerlemesi', 'Modernliğin durma noktasına gelmiş olması', 'Modernliğin yalnızca ulaşım ve taşımacılık teknolojisindeki gelişmelerden ibaret olması'], 'Giddens\'ın "Jagannath arabası" benzetmesi, modernliğin kolektif olarak yönlendirilebilse de her an kontrolden çıkabilecek bir güç olduğunu anlatır.'),
  ('Giddens\'ın "Mahremiyetin Dönüşümü"nde tanımladığı "saf ilişki" kavramının ayırıcı özelliği hangisidir?', 'İlişkinin, tarafların ondan doyum sağladığı sürece sürmesi', ['İlişkinin akrabalar tarafından düzenlenmesi', 'İlişkinin yalnızca ekonomik çıkara dayanması', 'İlişkinin dinsel ve hukuki olarak yaşam boyu bozulamaz sayılması'], 'Saf ilişki dış etkenlere değil, iki kişinin duygusal ve cinsel doyumuna dayanır; doyum sona erdiğinde ilişki de sona erebilir.'),
  ('Beck\'in "düşünümsel modernleşme" kavramı neyi anlatır?', 'Modernliğin kendi ürettiği risklerle yüzleşip kendini sorgulamasını', ['Geleneksel toplumun ilk kez sanayileşmesini', 'Bilimsel bilginin bütün kuşkulardan arınmasını', 'Toplumların modernlikten bütünüyle geri dönüp geleneksel yaşam biçimlerine yönelmesini'], 'Beck\'e göre birinci modernlik doğayı ve geleneği dönüştürürken, ikinci (düşünümsel) modernlik kendi yan etkileriyle uğraşmak zorunda kalan bir modernliktir.'),
  ('Zygmunt Bauman\'ın "Modernite ve Holokost" adlı eserinde savunduğu temel görüş hangisidir?', 'Holokost\'un modern bürokrasi ve teknik akılcılığın koşullarında mümkün olduğu', ['Holokost\'un modernlik öncesi barbarlığa dönüşten ibaret olduğu', 'Holokost\'un yalnızca birkaç bireyin kişisel nefretinden ve ruhsal bozukluklarından kaynaklandığı', 'Holokost\'un modern toplumla hiçbir bağlantısı olmadığı'], 'Bauman, iş bölümü, kurala bağlı itaat ve ahlaki sorumluluğun dağıtılması gibi modern bürokratik özelliklerin kitlesel imhayı örgütlenebilir kıldığını ileri sürdü.'),
  ('Bauman\'ın "Yasa Koyucular ve Yorumcular" adlı eserine göre modernlikten postmodernliğe geçişte aydınların rolü nasıl değişmiştir?', 'Doğruyu belirleyen otoriteden gelenekler arası çevirmenliğe', ['Yorumculuktan devletin resmî yasa koyucusu ve ideoloğu olmaya', 'Siyasetten tümüyle çekilip yalnızca sanatla uğraşmaya', 'Halkın oylarıyla seçilen yöneticiler olmaya'], 'Bauman\'a göre modern aydın evrensel doğrular adına yasa koyucu iddiası taşırken, postmodern koşullarda farklı topluluklar arasında anlam aktaran bir yorumcuya dönüşür.'),
  ('Norbert Elias\'ın kendi sosyolojik yaklaşımına ad olarak verdiği ve bireylerin karşılıklı bağımlılık ağlarını anlatan kavram hangisidir?', 'Figürasyon', ['Yapılaşma', 'Otopoiesis', 'Habitus ve alan'], 'Elias birey ile toplumu ayrı varlıklar olarak görmeyi reddetti; insanların birbirine bağımlı olarak oluşturduğu değişken ağları figürasyon olarak adlandırdı.'),
  ('Elias ve Scotson\'ın bir İngiliz kasabasında yaptıkları araştırmada, aynı sınıftan olmalarına karşın eski yerleşiklerin yeni gelenleri dışlamasını açıklayan temel etken hangisidir?', 'Eski yerleşiklerin uzun birliğinden gelen güçlü kaynaşma', ['Eski yerleşiklerin yeni gelenlerden çok daha zengin ve eğitimli olması', 'İki grubun farklı dinlere mensup olması', 'Yeni gelenlerin farklı bir dil konuşması'], '"Kurulu Düzenler ve Yabancılar" çalışmasında iki grup arasında gelir, din ya da etnik fark yoktu; belirleyici olan eski yerleşiklerin uzun süreli birliğinin sağladığı örgütlülük ve damgalama gücüydü.'),
  ('Elias\'ın Eric Dunning ile birlikte geliştirdiği spor sosyolojisine göre modern sporun işlevi hangisidir?', 'Denetimli bir ortamda heyecan ve gerilim yaşamaya olanak vermesi', ['Toplumdaki bütün şiddet eğilimlerini tümüyle ve kalıcı olarak ortadan kaldırması', 'Yalnızca askerî eğitim amacı taşıması', 'Bireylerin duygularını tamamen bastırması'], 'Elias ve Dunning\'e göre uygarlık süreciyle duyguları denetlemeye alışan modern insan, sporda kurallarla sınırlanmış ve güvenli bir heyecan arayışını doyurur.'),
  ('Baudrillard\'ın, aslı olmayan ya da aslıyla bağı kopmuş kopyalar için kullandığı kavram hangisidir?', 'Simülakr', ['Totem', 'İdeal tip', 'Aura'], 'Baudrillard\'a göre postmodern kültürde imgeler artık bir gerçekliği yansıtmaz; kendisinden başka bir şeye gönderme yapmayan simülakrlar dolaşımdadır.'),
  ('Richard Sennett\'in "Karakterin Aşınması" adlı eserine göre esnek kapitalizmde kısa süreli işler ve sürekli değişen projeler çalışanları nasıl etkiler?', 'Uzun vadeli hedefler ve tutarlı bir yaşam öyküsü kurmalarını zorlaştırır', ['Onlara ömür boyu iş güvencesi sağlar', 'Sadakat ve güven bağlarını kendiliğinden güçlendirip işyerine bağlılığı artırır', 'Mesleki kimliklerini değişmez kılar'], 'Sennett\'e göre "uzun vade yok" ilkesi güven, bağlılık ve karakter gibi zaman içinde gelişen nitelikleri aşındırır.'),
  ('Daniel Bell\'e göre sanayi sonrası toplumda yeniliğin ve politikanın temel kaynağı olarak öne çıkan şey hangisidir?', 'Kuramsal bilgi', ['Toprak mülkiyeti', 'Kas gücü', 'Dinsel gelenek'], 'Bell\'e göre sanayi toplumunda sermaye ve emek belirleyiciyken, sanayi sonrası toplumda üniversite ve araştırma kurumlarında üretilen kuramsal bilgi merkezi konuma gelir.'),
  ('Daniel Bell\'in 1960 tarihli ve Batı\'da büyük ideolojik tutkuların sönmeye yüz tuttuğunu öne süren eseri hangisidir?', 'İdeolojinin Sonu', ['Tarihin Sonu', 'Büyük Dönüşüm', 'Kitle İnsanı ve Toplum'], 'Bell, refah devleti ve karma ekonomi üzerinde uzlaşma sağlanmasıyla ideolojik kutuplaşmanın zayıfladığını savundu. "Tarihin Sonu" ise Fukuyama\'ya aittir.'),
  ('Charlotte Perkins Gilman\'ın 1898 tarihli "Kadınlar ve Ekonomi" adlı eserinde kadınların ikincil konumunu açıklarken öne çıkardığı etken hangisidir?', 'Kadınların ekonomik olarak erkeklere bağımlı kılınması', ['Kadınların doğuştan daha az yetenekli olması', 'Kadınların eğitim almayı istememesi', 'Kadınların dinsel kurumlardan dışlanması'], 'Gilman, kadınların ücretli üretimden dışlanıp geçimlerini evlilik yoluyla sağlamak zorunda bırakılmasının eşitsizliğin temel kaynağı olduğunu savundu.'),
  ('İngiliz sosyolog Ann Oakley\'nin 1970\'lerdeki çalışmalarının sosyolojiye en önemli katkısı hangisidir?', 'Ev işini incelenmesi gereken bir emek biçimi olarak ele alması', ['Ev işinin hiçbir toplumsal ve ekonomik önemi olmadığını kanıtlaması', 'Kadınların yalnızca annelik için yaratıldığını savunması', 'Aile kurumunun ortadan kalktığını göstermesi'], 'Oakley, ev kadınlarıyla yaptığı görüşmelerle ev işinin tekdüze, yalıtılmış ve değeri tanınmayan bir çalışma olduğunu gösterdi; bu konuyu sosyolojinin gündemine taşıdı.'),
  ('Dorothy E. Smith\'in "duruş noktası" (bakış açısı) kuramının temel savı hangisidir?', 'Kadınların gündelik deneyiminden bakmanın egemen bakışın gizlediğini görünür kılacağı', ['Bütün bilimsel bilginin tek, evrensel ve tümüyle tarafsız bir bakış açısından üretilebileceği', 'Kadınların deneyiminin bilim için önemsiz olduğu', 'Sosyolojinin yalnızca istatistiklerle yapılması gerektiği'], 'Smith, ana akım sosyolojinin erkeklerin yönetici dünyasından bakan bir bilgi ürettiğini; kadınların gündelik yaşamından başlayan bir sosyolojinin bu bilgiyi düzeltebileceğini savundu.'),
  ('R. W. Connell\'in bir toplumda erkekliğin diğer erkeklik biçimlerini ve kadınlığı ikincil konuma iten egemen ve idealleştirilmiş biçimi için kullandığı kavram hangisidir?', 'Hegemonik erkeklik', ['Ataerkil kast', 'Araçsal ve dışavurumcu rol', 'Ana statü'], 'Connell, erkekliğin tek tip olmadığını; toplumsal cinsiyet düzeninde egemen bir erkeklik idealinin diğer erkeklikleri de hiyerarşi içinde konumlandırdığını gösterdi.'),
  ('Parsons\'ın aile içinde kadına dışavurumcu, erkeğe araçsal rol yükleyen görüşüne feminist sosyologların yönelttiği temel eleştiri hangisidir?', 'Toplumsal olarak kurulan bir iş bölümünü doğal ve işlevsel gibi sunması', ['Aile kurumunu hiç incelememesi', 'Kadınların ücretli işteki payını abartması', 'Aile içinde hiçbir rol farklılaşmasının bulunmadığını ve rollerin eşit olduğunu ileri sürmesi'], 'Feministler, Parsons\'ın rol ayrımını toplumun dengesi için gerekli göstererek ataerkil iş bölümünü meşrulaştırdığını ve kadınların bağımlılığını görünmez kıldığını savundu.'),
  ('Du Bois\'nın akademik çalışmalarının yanı sıra 1909\'da kurucuları arasında yer aldığı ve siyahların yurttaşlık hakları için mücadele eden örgüt hangisidir?', 'NAACP', ['Amerikan Sosyoloji Derneği', 'Birleşmiş Milletler', 'Uluslararası Kızılhaç'], 'Du Bois NAACP\'nin kurucuları arasındaydı ve derneğin yayın organı The Crisis\'in uzun süre editörlüğünü yaptı.'),
  ('İsveçli iktisatçı Gunnar Myrdal\'ın 1944 tarihli "Bir Amerikan İkilemi" adlı eserinde ele aldığı ikilem hangisidir?', 'Amerikan eşitlik inancı ile siyahlara yönelik ayrımcılık arasındaki çelişki', ['Tarım ve sanayi arasında yatırım tercihi', 'Kuzey ile güney eyaletleri arasındaki iklim ve tarım ürünleri farkının yarattığı gerilim', 'Göçü teşvik etmek ile sınırlamak arasındaki seçim'], 'Myrdal, Amerikalıların benimsediği eşitlik idealleri ile ırk ayrımcılığı pratikleri arasındaki çelişkiyi "Amerikan ikilemi" olarak adlandırdı.'),
  ('William Julius Wilson\'ın 1978 tarihli "Irkın Azalan Önemi" adlı eserinde savunduğu görüş hangisidir?', 'Siyahların yaşam şanslarında sınıf konumunun giderek daha belirleyici olduğu', ['Irk ayrımcılığının ABD\'de tümüyle sona erdiği', 'Sınıfın hiçbir zaman önemli bir etken olmadığı', 'Siyahların tümünün aynı ekonomik koşullarda yaşadığı ve aralarında sınıf farkı olmadığı'], 'Wilson, sanayisizleşme ve kent ekonomisindeki değişimlerle siyah orta sınıf yükselirken kent merkezlerindeki yoksulların durumunun ağırlaştığını; sınıfın belirleyiciliğinin arttığını savundu.'),
  ('William Graham Sumner\'ın 1906 tarihli "Halk Yolları" (Folkways) adlı eserinde, bir toplumun ahlaki açıdan zorunlu saydığı ve çiğnenmesi sert tepki doğuran törelerine verdiği ad hangisidir?', 'Mores', ['Folkways', 'Anomi', 'Habitus'], 'Sumner gündelik alışkanlıkları folkways, toplumun refahı için zorunlu görülen ve ahlaki yük taşıyan kuralları ise mores olarak ayırdı.'),
  ('Sumner\'ın "Toplumsal Sınıflar Birbirine Ne Borçludur?" adlı yazısında savunduğu tutum hangisidir?', 'Devletin yoksullara yardım etmemesini savunan bırakınız yapsınlar anlayışı', ['Bütün mülklerin devletleştirilmesi gerektiği', 'Sınıfların devrimle ortadan kaldırılması gerektiği', 'Zenginlerin servetlerinin tümünü gönüllü olarak ya da yasayla zorlanarak yoksullara dağıtması gerektiği'], 'Sumner, Spencer\'dan etkilenen bir sosyal Darwinist olarak devletin yeniden dağıtım politikalarına karşı çıktı ve bireyin kendi başının çaresine bakması gerektiğini savundu.'),
  ('Robert ve Helen Lynd\'in 1920\'lerde Indiana eyaletindeki Muncie kentini takma bir adla inceledikleri ünlü topluluk araştırması hangisidir?', 'Middletown', ['Yankee City', 'Cornerville', 'Springdale'], 'Lynd çifti "Middletown" adıyla yayımladıkları çalışmada sıradan bir Amerikan kentinde iş, ev yaşamı, eğitim, boş zaman, din ve topluluk etkinliklerini sistemli biçimde betimledi.'),
  ('William Foote Whyte\'ın Boston\'daki İtalyan kökenli bir mahallede yıllarca yaşayarak gençlerin sokak köşesi gruplarını incelediği eser hangisidir?', 'Sokak Köşesi Toplumu', ['Kentli Köylüler', 'Tally\'nin Köşesi ve Kent Yaşamı', 'Örgüt İnsanı'], 'Whyte\'ın "Street Corner Society" çalışması, "Doc" adlı kilit bilgi verenin yardımıyla yapılan katılımcı gözlemin klasik örneğidir ve yoksul mahallenin aslında güçlü bir toplumsal örgütlenmesi olduğunu gösterdi.'),
  ('Herbert Gans\'ın yoksulluğun neden ortadan kalkmadığını işlevselci bir dille tartıştığı makalesinde ileri sürdüğü düşünce hangisidir?', 'Yoksulluğun varlıklı kesimler için çeşitli işlevler görmesi', ['Yoksulluğun tümüyle bireysel tembellikten ve kişisel başarısızlıktan kaynaklanması', 'Yoksulluğun hiçbir toplumda bulunmaması', 'Yoksulluğun yalnızca kırsal kesimde görülmesi'], 'Gans, yoksulların düşük ücretli ve kirli işleri yapması, sosyal hizmet mesleklerine iş sağlaması gibi işlevlerini sıralayarak yoksulluğun sürmesinin kimin işine yaradığını sorguladı.'),
  ('Paul Lazarsfeld ve arkadaşlarının 1940 ABD başkanlık seçimi üzerine yaptıkları araştırmaya göre medya mesajları seçmenlere genellikle nasıl ulaşır?', 'Önce kanaat önderlerine, onlardan da çevrelerindeki kişilere', ['Doğrudan ve hiçbir aracı olmadan bütün seçmenlere aynı anda ve eşit biçimde', 'Yalnızca siyasal partilerin üyelerine', 'Yalnızca resmî devlet kanallarıyla'], '"Halkın Seçimi" araştırması iki aşamalı iletişim akışı modelini ortaya koydu: medya etkisi büyük ölçüde kişisel ilişkiler ve kanaat önderleri aracılığıyla yayılır.'),
  ('Neil Smelser\'in kolektif davranışı açıklayan "değer eklemeli" kuramına göre bir toplumsal hareketin ortaya çıkması için ne gerekir?', 'Birbirini izleyen altı koşulun aşamalı olarak birikmesi', ['Tek bir karizmatik liderin ortaya çıkması tek başına yeterlidir', 'Yalnızca ekonomik bir bunalım yaşanması yeterlidir', 'Hiçbir koşula gerek yoktur, hareketler rastlantısaldır'], 'Smelser yapısal elverişlilik, gerilim, genelleşmiş inanç, tetikleyici etken, harekete geçirme ve toplumsal denetim olmak üzere altı belirleyicinin sırayla eklenmesi gerektiğini savundu.'),
  ('Alvin Gouldner\'ın sosyolojiye kazandırdığı "karşılıklılık normu" neyi anlatır?', 'İyiliğe iyilikle karşılık verilmesi yönündeki yaygın beklentiyi', ['Herkesin aynı ücreti alması gerektiği ilkesini', 'Kuralların yalnızca güçlüler için geçerli olmasını', 'Devletin vatandaşlarına karşı hiçbir yükümlülüğü bulunmamasını ve yalnızca itaat beklemesini'], 'Gouldner, iyiliğe iyilikle karşılık verme beklentisinin hemen her toplumda bulunduğunu ve toplumsal ilişkileri dengede tutan temel normlardan biri olduğunu ileri sürdü.'),
  ('Mannheim\'ın "Kuşaklar Sorunu" makalesine göre bir kuşağı sosyolojik olarak birleştiren temel etken hangisidir?', 'Gençlikte aynı tarihsel olayları ortak bir konumdan yaşamak', ['Yalnızca aynı yılda ve aynı ülkede doğmuş olmak, başka hiçbir koşul aranmaz', 'Aynı aileden gelmek', 'Aynı mesleği yapmak'], 'Mannheim\'a göre aynı dönemde doğmak tek başına yetmez; biçimlendirici gençlik yıllarında büyük olayları birlikte yaşamak ortak bir kuşak bilinci yaratır.'),
  ('Karl Polanyi\'nin "Büyük Dönüşüm" adlı eserine göre piyasa ekonomisinin emek, toprak ve parayı metalaştırması neden sorunludur?', 'Bunların satılmak için üretilmemiş kurgusal metalar olması', ['Bunların hiçbir ekonomik değerinin bulunmaması', 'Bunların yalnızca devlet tarafından üretilebilmesi', 'Bunların ticaretinin tarih boyunca hiçbir toplumda ve hiçbir dönemde yapılmamış olması'], 'Polanyi emeğin insanın kendisi, toprağın doğa, paranın ise bir değer işareti olduğunu; bunları sıradan mal gibi piyasaya bırakmanın toplumu ve doğayı yıkıma sürükleyeceğini savundu.'),
  ('Polanyi\'nin "çifte hareket" kavramı neyi anlatır?', 'Piyasanın genişlemesine karşı toplumun kendini koruma tepkileri geliştirmesini', ['Ekonominin aynı anda hem büyüyüp hem küçülmesini', 'Nüfusun kırdan kente ve kentten kıra aynı anda ve aynı yoğunlukta göç etmesini', 'İki ülkenin karşılıklı ticaret anlaşması yapmasını'], 'Polanyi\'ye göre piyasanın kendini düzenleme iddiasıyla yayılmasına karşı işçi yasaları, sosyal korumalar ve sendikalar gibi toplumu koruyan bir karşı hareket doğar.'),
  ('Paul Willis\'in "Çalışmayı Öğrenmek" adlı araştırmasında okulda kurallara karşı çıkan işçi sınıfı kökenli gençlerin durumu için ulaştığı sonuç hangisidir?', 'Okul karşıtı kültürlerinin onları işçi sınıfı işlerine yönlendirdiği', ['Bu gençlerin tümünün üniversiteye gittiği', 'Okulun bu gençleri başarılı öğrencilere dönüştürüp orta sınıf mesleklerine taşıdığı', 'Bu gençlerin hiçbir alt kültür geliştirmediği'], 'Willis\'in incelediği "lads" grubu zihinsel işi küçümseyip el emeğini erkeklikle özdeşleştirdi; böylece direniş kültürleri farkında olmadan sınıf konumlarının yeniden üretilmesine katkı yaptı.'),
  ('Bowles ve Gintis\'in "Kapitalist Amerika\'da Okul" adlı eserinde ileri sürdükleri "uygunluk ilkesi" neyi anlatır?', 'Okuldaki hiyerarşi ve disiplinin işyeri ilişkilerini yansıtması', ['Okul müfredatının öğrencilerin ilgi alanlarına ve bireysel yeteneklerine uygun olarak hazırlanması', 'Öğretmen sayısının öğrenci sayısına uygun olması', 'Okul binalarının sağlık koşullarına uygun yapılması'], 'Bowles ve Gintis\'e göre okul, itaat, dakiklik ve dışsal ödüllere göre çalışma gibi alışkanlıklar kazandırarak öğrencileri kapitalist işyerindeki konumlarına hazırlar.'),
  ('Putnam\'ın "Demokrasiyi İşletmek" adlı eserinde İtalya\'nın kuzey ve güney bölgelerindeki yerel yönetimlerin başarı farkını açıklarken öne çıkardığı etken hangisidir?', 'Yurttaşların derneklere katılımı ve karşılıklı güven gelenekleri', ['Bölgelerin iklim ve toprak verimliliği farkı', 'Merkezî hükümetin bölgelere ayırdığı bütçe', 'Bölgelerdeki nüfusun yaş ortalaması, doğum oranları ve göç hareketleri'], 'Putnam, koro, spor kulübü ve dernek gibi yatay örgütlenmelerin güçlü olduğu kuzeyde yurttaşlık geleneklerinin ve güvenin yönetim başarısını artırdığını savundu.'),
  ('James Coleman\'ın sosyal sermaye anlayışında, ebeveynlerin birbirini tanıdığı ve çocukların arkadaşlarının ailelerinin de birbirleriyle ilişki içinde olduğu sıkı ağların önemi neye dayanır?', 'Normların uygulanmasını ve karşılıklı denetimi kolaylaştırmasına', ['Ailelerin gelirlerini doğrudan artırmasına', 'Devlet okullarını gereksiz hale getirmesine', 'Çocukların birbirinden yalıtılmasını sağlamasına'], 'Coleman bu özelliğe ağların kapalılığı der. Kapalı ağlarda yetişkinler birlikte davranarak çocuklar için ortak kurallar koyabilir ve uygulayabilir.'),
  ('Viviana Zelizer\'in "Paha Biçilmez Çocuğu Fiyatlandırmak" adlı çalışmasında ABD\'de 19. yüzyıl sonundan 20. yüzyıl başına çocuğun değerine ilişkin gösterdiği değişim hangisidir?', 'Yararlı bir işçi olmaktan, ekonomik açıdan yararsız ama paha biçilmez olmaya', ['Duygusal değerden ekonomik yarar sağlayan işçiye', 'Yalnızca hukuki bir varlıktan dinsel bir varlığa', 'Ailenin mirasçısından devletin askerine'], 'Zelizer, çocuk işçiliğinin yasaklanmasıyla çocuğun ekonomik katkısının azaldığını, buna karşılık duygusal değerinin arttığını; sigorta ve tazminat uygulamalarının da bunu yansıttığını gösterdi.'),
  ('Durkheim okulundan Maurice Halbwachs\'ın sosyolojiye kazandırdığı ve bireylerin geçmişi hatırlama biçiminin içinde yer aldıkları grupların çerçevelerine bağlı olduğunu anlatan kavram hangisidir?', 'Kolektif bellek', ['Kolektif bilinçdışı', 'Bireysel bellek', 'Kültürel gecikme'], 'Halbwachs, belleğin tümüyle bireysel olmadığını; aile, din ya da sınıf gibi grupların hatırlamanın toplumsal çerçevelerini sağladığını savundu.'),
  ('Henri Lefebvre\'in kentlilerin kentsel yaşamı biçimlendirme ve kentin olanaklarından yararlanma talebini anlatmak için kullandığı kavram hangisidir?', 'Kent hakkı', ['Akışlar uzamı', 'Geçiş bölgesi', 'İstila ve ardıllık'], 'Lefebvre 1968\'de yayımladığı "Kent Hakkı" kitabında kentin metaya dönüşmesine karşı kullanıcılarının kente katılma ve onu dönüştürme hakkını savundu.'),
  ('Saskia Sassen\'in "küresel kent" kavramıyla nitelediği ve küresel ekonominin yönetim ve finans işlevlerinin yoğunlaştığı üç kent hangileridir?', 'New York, Londra ve Tokyo', ['Paris, Roma ve Madrid', 'Moskova, Pekin ve Yeni Delhi', 'Kahire, Lagos ve Nairobi'], 'Sassen 1991 tarihli "Küresel Kent" adlı eserinde bu üç kentin dünyaya dağılmış üretimi yöneten finans ve ileri hizmet merkezleri haline geldiğini gösterdi.'),
  ('Amitai Etzioni\'nin örgütleri üyeleri üzerinde uyguladıkları denetim türüne göre sınıflandırmasında, cezaevleri gibi zor kullanarak uyum sağlayan örgütlere verdiği ad hangisidir?', 'Zorlayıcı örgütler', ['Yararcı örgütler', 'Normatif örgütler', 'Gönüllü ve hayırsever örgütler'], 'Etzioni örgütleri zorlayıcı (cezaevi), yararcı (ücretle çalışılan şirket) ve normatif (dinî ya da gönüllü kuruluş) olarak üç tipe ayırdı.'),
  ('Barney Glaser ve Anselm Strauss\'un geliştirdiği "temellendirilmiş kuram" yaklaşımının ayırıcı özelliği hangisidir?', 'Kuramın toplanan verilerden adım adım oluşturulması', ['Önceden kurulmuş ve kesinleşmiş bir kuramın yalnızca laboratuvar deneyleriyle sınanması', 'Araştırmanın hiçbir veri toplamadan yürütülmesi', 'Yalnızca resmî istatistiklerin kullanılması'], 'Glaser ve Strauss, ölmekte olan hastalar üzerine yaptıkları çalışmalarda kavramların veriden sürekli karşılaştırmayla türetildiği tümevarımcı bir nitel yöntem geliştirdi.'),
  ('Ernest Gellner\'ın milliyetçilik kuramına göre ulusların ve milliyetçiliğin ortaya çıkışında belirleyici olan dönüşüm hangisidir?', 'Tarım toplumundan standart eğitim isteyen sanayi toplumuna geçiş', ['Orta Çağ\'da feodal beyliklerin güçlenip krallıkların merkezî otoritesini zayıflatması', 'Avcı-toplayıcılıktan tarıma geçiş', 'Dinsel cemaatlerin güçlenmesi'], 'Gellner\'a göre sanayi toplumu ortak bir dil ve okuryazarlık kültürü gerektirir; devletin denetlediği kitlesel eğitim bu yüksek kültürü yayar ve milliyetçiliği doğurur.'),
  ('Giddens\'ın yapılaşma kuramı, Bourdieu\'nün habitus-alan yaklaşımı ve Elias\'ın figürasyon sosyolojisi arasındaki ortak amaç hangisidir?', 'Birey ile toplum, eylem ile yapı arasındaki ikiliği aşmak', ['Toplumu yalnızca ekonomik yapıyla açıklamak', 'Sosyolojiyi doğa bilimlerine indirgemek', 'Yalnızca bireylerin psikolojik ve kalıtsal özelliklerini ayrıntılı biçimde incelemek'], 'Bu üç kuramcı da toplumu ya yalnızca yapılar ya da yalnızca bireysel eylemler üzerinden açıklayan yaklaşımlara karşı çıkarak ikisini birlikte düşünmeye çalıştı.'),
  ('Bir sosyolog, Türkiye\'deki dizilerin Orta Doğu ve Latin Amerika\'da izlenmesini, kültürel ürünlerin yalnızca Batı\'dan dünyaya değil, farklı merkezlerden çok yönlü aktığına örnek olarak gösteriyor. Bu değerlendirme hangi görüşü sorgulamaktadır?', 'Küreselleşmenin tek yönlü bir Batılılaşma olduğu görüşünü', ['Kültürün doğuştan gelmeyip toplumsal etkileşimle öğrenildiği ve aktarıldığı görüşünü', 'Kitle iletişiminin etkili olduğu görüşünü', 'Toplumların zamanla değiştiği görüşünü'], 'Appadurai ve Robertson gibi kuramcılar, küresel kültürel akışların çok merkezli olduğunu ve tek yönlü bir kültür emperyalizmi modelinin yetersiz kaldığını vurgular.'),
  ('Weber\'in anlayıcı sosyolojisi ile Durkheim\'ın pozitivist sosyolojisi karşılaştırıldığında aralarındaki temel yöntemsel fark hangisidir?', 'Weber öznel anlamı kavramayı, Durkheim olguları dışsal şeyler gibi incelemeyi öne çıkarır', ['İkisi de yalnızca deney yöntemini kullanır', 'Durkheim eylemcinin öznel anlamını, Weber ise toplumsal olguların dışsallığını ve zorlayıcılığını öne çıkarır', 'İkisi de sosyolojinin bilim olamayacağını savunur'], 'Weber eylemcinin bakış açısını anlamadan nedensel açıklamanın eksik kalacağını düşünür; Durkheim ise toplumsal olguları bireysel bilinçlerden bağımsız dış gerçeklikler olarak ele alır.'),
  ('Aşağıdaki kuramcı-kavram eşleştirmelerinden hangisi yanlıştır?', 'Georg Simmel - demir kafes', ['Emile Durkheim - anomi', 'Karl Marx - yabancılaşma', 'Erving Goffman - total kurum'], 'Demir kafes benzetmesi Max Weber\'e aittir. Diğer eşleştirmeler doğrudur.'),
  ('Bir öğrenci sosyologları ve kavramlarını eşleştirirken bir yanlışlık yapmıştır. Hatalı eşleştirme hangisidir?', 'Robert Merton - kolektif coşku', ['Pierre Bourdieu - habitus', 'Anthony Giddens - ontolojik güvenlik', 'Zygmunt Bauman - akışkan modernlik'], 'Kolektif coşku Emile Durkheim\'ın din sosyolojisindeki kavramıdır. Merton ise açık-örtük işlev, anomi kuramı ve referans grubu gibi kavramlarla tanınır.'),
  ('Weber\'in "Siyaset Meslek Olarak" konferansında siyaseti "sert tahtaları hem tutku hem de sağduyuyla yavaş yavaş delmek" diye tanımlaması neyi vurgular?', 'Siyasetin sabır, kararlılık ve gerçekçilik isteyen uzun soluklu bir uğraş olduğunu', ['Siyasetin kısa sürede, fazla çaba harcamadan kolayca somut sonuç veren basit bir uğraş olduğunu', 'Siyasette duygulara hiç yer olmadığını', 'Siyasetin yalnızca marangozluk gibi el becerisine dayandığını'], 'Weber bu benzetmeyle siyasetçinin hem tutku hem de sorumluluk duygusu ve ölçülülükle uzun süre direnç göstermesi gerektiğini anlatır.'),
  ('Foucault\'nun "Hapishanenin Doğuşu"nda Platoncu bir deyişi tersine çevirerek kurduğu "Ruh, bedenin hapishanesidir" cümlesi neyi anlatır?', 'Disiplinin bireye yerleştirdiği ruhun bedeni denetleyen bir araca dönüşmesini', ['Bedenin ruhu tutsak eden bir kafes olduğunu', 'Ruhun ölümden sonra özgürleştiğini', 'Hapishanelerin yalnızca ruhsal hastalığı bulunan kişiler için kurulmuş özel kurumlar olduğunu'], 'Foucault\'ya göre modern iktidar ruhu, yani bilinç, vicdan ve kişiliği biçimlendirerek bedeni içeriden yönetir; böylece Platon\'un bedeni ruhun hapishanesi sayan sözü tersine döner.'),
  ('Polonya\'da doğan, 1968\'de yaşanan antisemitik kampanya sonrasında ülkesinden ayrılan ve uzun yıllar İngiltere\'deki Leeds Üniversitesi\'nde ders veren sosyolog kimdir?', 'Zygmunt Bauman', ['Norbert Elias', 'Karl Mannheim', 'Ralf Dahrendorf'], 'Bauman Varşova Üniversitesi\'ndeki görevinden uzaklaştırıldıktan sonra İsrail\'e, ardından İngiltere\'ye geçti ve Leeds Üniversitesi\'nde çalıştı.'),
  ('Norbert Elias\'ın en önemli eseri "Uygarlık Süreci" 1939\'da yayımlandığı halde uzun süre geniş ilgi görmemiştir. Eserin ancak 1970\'lerde yaygın tanınmasının en önemli nedeni hangisidir?', 'Savaş ve sürgün koşullarında yayımlanıp çevirisinin geç yapılması', ['Eserin yayımlanır yayımlanmaz Nazi rejimince yasaklanıp bütün kopyalarının yakılması', 'Elias\'ın eseri takma adla yazması', 'Eserin yalnızca Latince basılması'], 'Elias Nazilerden kaçarak İngiltere\'ye yerleşti. Kitabı İkinci Dünya Savaşı arifesinde İsviçre\'de Almanca çıktı; yeni basımı ve çevirileri 1969 ve sonrasında yapılınca geniş kitlelere ulaştı.'),
  ('Max Weber\'in eşi olup kadın hakları savunucusu ve sosyolog olarak çalışan, Weber\'in ölümünden sonra eserlerini yayıma hazırlayan kişi kimdir?', 'Marianne Weber', ['Rosa Luxemburg', 'Lou Andreas-Salomé', 'Clara Zetkin'], 'Marianne Weber evlilik ve hukuk üzerine eserler yazdı, kadın hareketinde etkin oldu ve kocasının biyografisini ve ölümünden sonra kalan eserlerini yayımladı.'),
  ('Sosyolojinin kurumsallaşmasıyla ilgili aşağıdaki olaylardan hangisi en erken tarihte gerçekleşmiştir?', 'Comte\'un sosyoloji terimini kullanması', ['Chicago Üniversitesi\'nde sosyoloji bölümünün kurulması', 'İstanbul Darülfünunu\'nda içtimaiyat kürsüsünün kurulması', 'Frankfurt\'ta Toplumsal Araştırmalar Enstitüsü\'nün kurulması'], 'Comte terimi 1830\'ların sonunda kullandı. Chicago bölümü 1892\'de, İstanbul\'daki kürsü 1914\'te, Frankfurt\'taki enstitü ise 1923\'te kuruldu.'),
  ('İbn Haldun\'a göre bir peygamberin ya da dinî davetin toplumda başarıya ulaşabilmesi için ne gereklidir?', 'Davetin güçlü bir asabiyetle desteklenmesi', ['Davetin yalnızca kentlerde yaşayan hadarilere yöneltilmesi', 'Davetçinin hiçbir gruba dayanmaması', 'Davetin yazılı yasalarla sınırlandırılması'], 'İbn Haldun, din ile asabiyetin birbirini güçlendirdiğini; arkasında güçlü bir dayanışma grubu bulunmayan dinî hareketlerin başarılı olamayacağını savunur.'),
  ('İbn Haldun\'un devletin evrelerine ilişkin görüşüne göre devletin ilk evresinde hükümdarın halkla ilişkisi nasıldır?', 'Hükümdar asabiyetin desteğiyle yönetir ve gücünü kavmiyle paylaşır', ['Hükümdar bütün yetkiyi tek başına toplar, kavmini dışlar ve paralı askerlere dayanır', 'Devlet lüks ve israf içinde çözülür', 'Hükümdar halka hiçbir biçimde görünmez'], 'İbn Haldun\'a göre kuruluş evresinde hükümdar asabiyet sahibi grubunun önderidir, onlardan ayrılmaz; sonraki evrelerde yetkiyi tekeline alır, refah ve israf artar ve devlet çöker.'),
  ('Ziya Gökalp\'in görüşüne göre bir milletin medeniyetini değiştirmesi ile harsını değiştirmesi arasındaki fark nedir?', 'Medeniyet başka milletlerden alınabilir, hars ise taklit edilemez', ['Hars başka milletlerden kolayca alınabilir, medeniyet ise hiçbir biçimde taklit edilemez', 'İkisi de başka milletlerden aynı kolaylıkla alınabilir', 'İkisi de hiçbir biçimde değişmez'], 'Gökalp\'e göre medeniyet yöntemle ve iradeyle yaratılıp aktarılabilen akla dayalı bir birikimdir; hars ise kendiliğinden oluşan duygu ve değerlerdir, taklitle edinilemez.'),
  ('İdris Küçükömer\'in "Düzenin Yabancılaşması" adlı eserinde Türk siyasal yaşamına ilişkin ileri sürdüğü tartışmalı görüş hangisidir?', 'Batıcı-laik kesimin bürokratik merkezi, İslamcı kesimin halk tabanını temsil ettiği', ['Türk siyasetinde hiçbir dönemde toplumsal kesimler arasında herhangi bir ayrılık ya da çatışma bulunmadığı', 'Bütün siyasal hareketlerin yalnızca dış güçlerce yönlendirildiği', 'Osmanlı\'da toprak mülkiyetinin tümüyle özel kişilere ait olduğu'], 'Küçükömer, alışılmış sol-sağ ayrımını tersine çeviren bir yorumla devlet merkezli Batıcı kadrolar ile esnaf ve halk tabanına dayanan dinî kesimler arasındaki ayrışmayı vurguladı.'),
  ('Nermin Abadan-Unat\'ın sosyolojiye en önemli katkılarından biri hangi konudaki araştırmalarıdır?', 'Türkiye\'den Avrupa\'ya işçi göçü ve göçmenlerin durumu', ['Osmanlı saray teşkilatı', 'Antik Anadolu\'da kent yerleşmeleri ve bunların çevre köylerle ilişkileri', 'Karadeniz\'de balıkçılık teknikleri'], 'Abadan-Unat, 1960\'lardan itibaren Almanya başta olmak üzere Avrupa\'ya giden Türk işçilerini ve ailelerini inceledi; "Bitmeyen Göç" bu çalışmaların özetidir.'),
  ('Montesquieu\'nün Paris\'i ziyaret eden iki İranlının mektupları biçiminde yazdığı ve Fransız toplumunu bir yabancının gözünden eleştirdiği eseri hangisidir?', 'İranlı Mektupları', ['Kanunların Ruhu Üzerine', 'Romalıların Yükseliş ve Çöküş Nedenleri', 'Toplum Sözleşmesi'], '"İranlı Mektupları" (1721), yabancı gözlemci tekniğiyle kendi toplumunun alışkanlıklarını tuhaf ve sorgulanabilir kılar; bu bakış sosyolojik mesafenin erken bir örneği sayılır.'),
  ('Tocqueville\'in demokratik toplumlarda yurttaşların kendi küçük özel dünyalarına çekilip yönetimi vesayetçi bir devlete bırakmasıyla ortaya çıkabileceğini düşündüğü tehlike hangisidir?', 'Yumuşak (vesayetçi) despotizm', ['Askerî diktatörlük', 'Teokratik yönetim', 'Feodal parçalanma ve beylik düzeni'], 'Tocqueville, eşitlik içindeki bireylerin kamusal yaşamdan çekilmesiyle onları zor kullanmadan, bir vasinin çocuğunu yönetmesi gibi yönlendiren yumuşak bir despotizmin doğabileceği uyarısında bulundu.'),
  ('Durkheim ile Mauss\'un 1903\'te yayımlanan "İlkel Sınıflandırma Biçimleri" adlı çalışmasının temel savı hangisidir?', 'Sınıflandırma kategorilerimizin toplumun örgütlenmesinden türediği', ['Sınıflandırma yeteneğinin tümüyle kalıtsal olduğu', 'İlkel toplumların hiçbir sınıflandırma yapmadığı', 'Sınıflandırma yapabilmenin yalnızca modern bilim insanlarına ve filozoflara özgü bir yetenek olduğu'], 'Durkheim ve Mauss, klan ve fratri gibi toplumsal bölünmelerin, insanların hayvanları, yönleri ve nesneleri gruplandırma biçiminin modeli olduğunu ileri sürdü.'),
  ('Durkheim\'ın işbölümünün anormal biçimlerinden biri olarak gördüğü "anomik işbölümü"ne en uygun örnek hangisidir?', 'Bunalım ve çatışmalarda işlevleri bağlayan kuralların yetersiz kalması', ['Bir köyde herkesin aynı işi yapması', 'Mesleklerin bireylerin yeteneklerine göre uyumlu, kendiliğinden ve adil biçimde dağılması', 'Bir ailede işlerin kuşaklar boyunca aynı kalması'], 'Durkheim\'a göre uzmanlaşma hızlandığında farklı işlevleri birbirine bağlayacak kurallar oluşmazsa, sanayide ve ticarette düzensizlik ve çatışma ortaya çıkar; bu anomik işbölümüdür.'),
  ('Weber\'in "Şehir" adlı incelemesine göre Orta Çağ Batı Avrupa kentini Doğu kentlerinden ayıran temel özellik hangisidir?', 'Kendi yasalarını yapan özerk bir yurttaşlar birliği olması', ['Kentlerin hiçbir surla çevrili olmaması', 'Kentlerde ticaretin yasak olması', 'Kentlerin yalnızca dinsel merkez ve hac yeri işlevi görmesi, ticaretle hiç ilgilenmemesi'], 'Weber, Batı kentinde yurttaşların kendi mahkemelerine, kurallarına ve yönetimlerine sahip bir birlik oluşturduğunu; bu özerkliğin kapitalizmin ve yurttaşlığın gelişiminde önemli olduğunu savundu.'),
  ('Weber\'e göre bir bilim insanının hangi konuyu araştıracağını seçerken kendi değerlerinden etkilenmesi ile araştırmanın sonuçlarını değerlendirmesi arasındaki ilişki nasıldır?', 'Konu seçiminde değerler rol oynayabilir, ama bulgular değer yargısı içermemelidir', ['Değerler araştırmanın hiçbir aşamasına giremez', 'Bulgular araştırmacının siyasal görüşüne ve ahlaki tercihlerine uygun biçimde yorumlanmalıdır', 'Konuyu yalnızca devlet belirlemelidir'], 'Weber "değerle ilişkilendirme" ile "değer yargısı"nı ayırır: araştırmacının ilgisi değerlere bağlıdır, ancak bilimsel çözümlemede kendi tercihlerini olgularmış gibi sunmamalıdır.'),
  ('Simmel\'in "kültürün trajedisi" olarak adlandırdığı durum hangisidir?', 'Nesnel kültür birikiminin bireyin özümseyebileceği ölçüyü aşması', ['Halk kültürünün tümüyle ortadan kalkması', 'Sanat eserlerinin müzelerden çalınıp özel koleksiyonlarda gizlenmesi ve halkın erişiminden çıkması', 'Kültürün yalnızca soylulara özgü olması'], 'Simmel\'e göre bilim, teknik ve sanatın nesnel birikimi giderek büyürken bireyin bu birikimden kendi kişiliğini geliştirmek için yararlanabildiği pay küçülür; birey yarattığı dünyaya yabancılaşır.'),
  ('Simmel\'in "Sır ve Gizli Dernekler" üzerine çözümlemesine göre gizli bir derneğin üyeleri arasındaki bağı güçlendiren temel etken hangisidir?', 'Paylaşılan sırrın üyeleri dışarıdakilerden ayırıp güven gerektirmesi', ['Üyelerin birbirini hiç tanımaması', 'Derneğin bütün etkinliklerini ve üye listesini düzenli olarak kamuya açık biçimde duyurması', 'Üyeliğin herkese açık olması'], 'Simmel\'e göre sır, sahiplerini ayrıcalıklı bir dünyada birleştirir; bu da sıkı bir sadakat ve iç disiplin gerektirerek grubun bütünleşmesini güçlendirir.'),
  ('Theda Skocpol\'un "Devletler ve Toplumsal Devrimler" adlı karşılaştırmalı çalışmasında incelediği üç devrim hangileridir?', 'Fransız, Rus ve Çin devrimleri', ['Amerikan, İngiliz ve Meksika devrimleri', 'İran, Küba ve Nikaragua devrimleri', 'Alman, İtalyan ve Macar devrimleri'], 'Skocpol bu üç devrimi karşılaştırarak devletin uluslararası baskılar altında çözülmesinin ve köylü ayaklanmalarının devrimci süreçteki belirleyici rolünü vurguladı.'),
  ('Charles Tilly\'nin Avrupa\'da modern devletin oluşumunu özetlediği "Savaş devleti yaptı, devlet de savaşı" sözü neyi anlatır?', 'Savaş için kaynak toplamanın vergi ve bürokrasiyi büyüterek devleti güçlendirdiğini', ['Modern devletlerin kurulmasıyla Avrupa\'da savaşların tümüyle ve kalıcı biçimde ortadan kalktığını', 'Savaşların yalnızca dinsel nedenlerle çıktığını', 'Devlet oluşumunun ticaretle hiçbir ilgisi olmadığını'], 'Tilly\'ye göre ordu kurmak ve savaşmak için vergi toplamak gerekti; bu da merkezî yönetimi ve bürokrasiyi büyüttü, güçlenen devletler de yeni savaşlar yürüttü.'),
  ('Seymour Martin Lipset\'in "Siyasal İnsan" adlı eserinde demokrasinin istikrarına ilişkin ileri sürdüğü ünlü sav hangisidir?', 'Ekonomik gelişme ve eğitim arttıkça demokrasinin kalıcılaşma olasılığının artması', ['Demokrasinin yalnızca yoksul ülkelerde başarılı olabileceği', 'Ekonomik gelişme düzeyinin demokrasinin kurulması ve sürmesiyle hiçbir biçimde ilişkili olmadığı', 'Demokrasinin yalnızca tek partili sistemlerde sürebileceği'], 'Lipset, zenginlik, kentleşme ve eğitimin geniş bir orta sınıf ve ılımlı bir siyasal kültür yaratarak demokrasiyi desteklediğini istatistiksel karşılaştırmalarla savundu.'),
  ('Ernst Troeltsch\'in Hristiyanlık tarihini incelerken geliştirdiği dinî örgütlenme tipolojisinde, toplumla uzlaşan, kapsayıcı ve doğuştan üyeliğe dayanan büyük örgüt tipine ne ad verilir?', 'Kilise', ['Mezhep', 'Kült', 'Tarikat'], 'Troeltsch kiliseyi toplumla bütünleşmiş ve geniş kitleleri kapsayan, mezhebi ise toplumdan ayrılan, seçkin ve gönüllü üyeliğe dayanan küçük gruplar olarak tanımladı.'),
  ('Thomas Luckmann\'ın "Görünmez Din" adlı eserinde modern toplumda dinin durumuna ilişkin savı hangisidir?', 'Dinin kurumsal kiliselerden bireysel anlam arayışlarına kaydığı', ['Dinin modern toplumda tamamen, kalıcı olarak ve bütün biçimleriyle yok olduğu', 'Dinin devletin resmî yönetimine geri döndüğü', 'Dinin yalnızca kırsal kesimde varlığını sürdürdüğü'], 'Luckmann, kilise katılımının azalmasını dinin ortadan kalkması olarak görmedi; anlam verme işlevinin özel alana ve bireysel seçimlere kaydığını savundu.'),
  ('Grace Davie\'nin İngiltere\'de dinî tutumları betimlemek için kullandığı "ait olmadan inanmak" ifadesi hangi durumu anlatır?', 'İnançlarını korurken kilise katılımı gibi kurumsal bağlarını gevşetmesini', ['İnsanların kiliseye düzenli gittiği halde hiçbir dinî öğreti ya da Tanrı inancı taşımamasını', 'Bütün inanç ve katılımın aynı oranda artmasını', 'Dinin yalnızca devlet törenlerinde yaşamasını'], 'Davie, İngiltere\'de Tanrı\'ya inanç oranının yüksek kaldığını ama kiliseye üyelik ve katılımın keskin biçimde düştüğünü gösterdi.'),
  ('Rodney Stark ve William Bainbridge gibi kuramcıların dini "dinî ekonomi" kavramıyla açıklayan yaklaşımına göre bir toplumda dinî canlılığı artıran etken hangisidir?', 'Birbiriyle rekabet eden çok sayıda dinî örgütün bulunması', ['Tek bir devlet kilisesinin tekel kurması', 'Dinî örgütlerin tümüyle yasaklanması', 'İnsanların dinî konulara ilgisinin doğuştan sabit olması ve hiçbir koşula göre değişmemesi'], 'Bu rasyonel seçim yaklaşımına göre dinsel çoğulculuk ve rekabet farklı ihtiyaçlara yanıt veren seçenekler sunar; tekelci yapılar ise tembelleşip katılımı azaltır. ABD bu görüşün başlıca örneğidir.'),
  ('Peter Berger\'in 1960\'larda savunduğu sekülerleşme tezini 1990\'larda nasıl değerlendirdiği bilinir?', 'Dinin pek çok yerde güçlendiğini görüp tezinin yanlış olduğunu kabul etmiştir', ['Sekülerleşmenin bütün dünyada tamamlandığını ve dinin artık kamusal bir rolü kalmadığını ilan etmiştir', 'Din sosyolojisini tümüyle bırakıp ekonomiye yönelmiştir', 'Görüşlerinde hiçbir değişiklik yapmamıştır'], 'Berger 1999\'da derlediği "Dünyanın Desekülerleşmesi" kitabında, Avrupa dışında dinin canlılığını koruduğunu ve modernleşmenin kaçınılmaz olarak sekülerleşme getirmediğini kabul etti.'),
  ('José Casanova\'nın "Modern Dünyada Kamusal Dinler" adlı eserinde sekülerleşme tezini ayrıştırırken savunduğu görüş hangisidir?', 'Dinin özel alana çekilmesinin modernliğin zorunlu sonucu olmadığı', ['Dinin modern toplumda hiçbir kamusal rolü kalmadığı ve tümüyle bireysel bir tercihe dönüştüğü', 'Sekülerleşmenin yalnızca Asya\'da yaşandığı', 'Dinin yalnızca bireysel ruh sağlığıyla ilgili olduğu'], 'Casanova sekülerleşmeyi farklılaşma, dinin gerilemesi ve özelleşme olarak üçe ayırdı; dinin kamusal alanda yeniden etkin olabileceğini (deprivatization) gösterdi.'),
  ('Herbert Marcuse\'nin "Eros ve Uygarlık" adlı eserinde Freud\'dan yola çıkarak geliştirdiği "artık baskı" kavramı neyi anlatır?', 'Uygarlığın gerektirdiğinin ötesinde, egemenliği korumak için uygulanan bastırmayı', ['Bebeklerin doğuştan getirdiği saldırganlık dürtüsünü', 'Bütün toplumlarda ve bütün tarihsel dönemlerde eşit düzeyde görülen zorunlu ve kaçınılmaz bastırmayı', 'Kentlerde artan nüfus yoğunluğunu ve kalabalığı'], 'Marcuse, belirli bir bastırmanın toplumsal yaşam için gerekli olduğunu kabul eder; ancak kapitalist toplumdaki baskının önemli bir kısmının egemenlik ilişkilerini sürdürmeye hizmet eden bir fazlalık olduğunu savunur.'),
  ('Erich Fromm\'un "Sahip Olmak ya da Olmak" adlı eserinde eleştirdiği yaşam yönelimi hangisidir?', 'İnsanın değerini mülk ve tüketimle ölçen sahip olma yönelimi', ['Paylaşmaya, sevmeye, üretmeye ve yaratıcı etkinliğe dayanan, insanı merkeze alan olma yönelimi', 'Doğayla uyum içinde yaşama ve sade tüketim isteği', 'Başkalarıyla dayanışma kurup topluluk yaşamına katılma'], 'Fromm modern tüketim toplumunda insanların kendilerini sahip olduklarıyla tanımladığını; oysa doyurucu bir yaşamın sevgi, üretkenlik ve paylaşma üzerine kurulan olma yöneliminde olduğunu savundu.'),
  ('Habermas\'ın 1973 tarihli "Meşruiyet Krizi" adlı eserine göre geç kapitalist toplumlarda devletin karşılaştığı temel sorun hangisidir?', 'Ekonomiyi yöneten devletin beklentileri karşılayamayınca desteğini yitirmesi', ['Devletin ekonomiye hiçbir biçimde karışmaması', 'Yurttaşların siyasete ve kamusal tartışmalara aşırı ilgi göstermesi nedeniyle karar alınamaması', 'Devletin vergi toplama yetkisini tümüyle yitirmesi'], 'Habermas\'a göre ekonomik bunalımları yönetmeye çalışan devlet, başarısız olduğunda ya da kararlarını açıklayamadığında meşruiyet kaybına uğrar.'),
  ('Habermas\'ın kimlikleri etnik köken ya da ortak kültür yerine demokratik anayasanın ilkelerine bağlılığa dayandıran yurttaşlık anlayışını anlatmak için kullandığı kavram hangisidir?', 'Anayasal yurtseverlik', ['Etnik milliyetçilik', 'Kültürel asimilasyon', 'Sivil din ve ulusal törenler'], 'Habermas çok kültürlü ve göçmen nüfusu büyük toplumlarda ortak bağın soy ya da dil değil, insan hakları ve demokratik usullere bağlılık olabileceğini savundu.'),
  ('John Urry\'nin turizm sosyolojisine kazandırdığı "turist bakışı" kavramı neyi anlatır?', 'Turistlerin yerleri toplumsal olarak biçimlenmiş bir bakışla seyretmesini', ['Turistlerin ziyaret ettikleri yerlere hiç bakmamasını', 'Turist rehberlerinin gezilerde yalnızca tarihî bilgi aktarıp yorum yapmaktan kaçınmasını', 'Turizmin ekonomik hiçbir etkisi olmamasını'], 'Urry, Foucault\'nun tıbbi bakışından esinlenerek turistin bakışının broşürler, fotoğraflar ve medya tarafından önceden kurulduğunu ve neyin görülmeye değer sayılacağını belirlediğini savundu.'),
  ('Howard Becker\'ın "Sanat Dünyaları" adlı eserinde sanat eserlerine ilişkin temel savı hangisidir?', 'Sanat eserinin birçok kişinin işbirliğiyle oluşan kolektif bir ürün olduğu', ['Sanat eserinin yalnızca sanatçının doğuştan getirdiği yeteneğin ve yalnız çalışmasının ürünü olduğu', 'Sanatın toplumsal koşullardan tümüyle bağımsız olduğu', 'Sanat eserlerinin değerinin yalnızca fiyatıyla belirlendiği'], 'Becker, malzeme üreticilerinden eleştirmenlere ve izleyicilere kadar uzanan işbirliği ağlarının ve ortak uzlaşımların neyin sanat sayılacağını belirlediğini gösterdi.'),
  ('Osmanlı siyasal düşüncesinde "daire-i adalet" olarak bilinen anlayışa göre adaletin toplumdaki yeri nedir?', 'Halkın refahını ve böylece ordu ile devletin varlığını sürdüren halkanın temelidir', ['Yalnızca saray görevlileri ve yüksek bürokratlar arasında geçerli olan bir görgü ve nezaket kuralıdır', 'Devletin varlığıyla hiçbir ilgisi olmayan bireysel bir erdemdir', 'Yalnızca savaş zamanında uygulanan bir askerî ilkedir'], 'Daire-i adalet anlayışında devlet askere, asker hazineye, hazine halkın üretimine, halk ise adalete dayanır; adalet bozulursa bütün halka çözülür.'),
  ('Charles Booth\'un 19. yüzyıl sonunda Londra\'da yürüttüğü büyük araştırmanın en bilinen ürünü hangisidir?', 'Sokakların gelir düzeyini renklerle gösteren yoksulluk haritaları', ['İngiltere\'nin ilk resmî nüfus sayımı ve buna dayanan ulusal doğum ve ölüm istatistikleri', 'Kraliyet ailesinin soy ağacı', 'Londra metrosunun ilk planı'], 'Booth "Londra Halkının Yaşamı ve Emeği" çalışmasında hane ziyaretleri ve gözlemlerle kentteki yoksulluğu belgeledi ve sokakları renk kodlarıyla haritalandırdı.'),
  ('Seebohm Rowntree\'nin York kentinde yaptığı yoksulluk araştırmasında "birincil yoksulluk" ile kastettiği durum hangisidir?', 'Gelirin en akıllıca harcansa bile temel gereksinimlere yetmemesi', ['Gelirin yeterli olduğu halde bir kısmının içki ya da kumar gibi başka harcamalara gitmesi sonucu düşülen yoksulluk', 'Yalnızca kırsal kesimde görülen geçici yoksulluk', 'Ailenin hiç çocuğu olmaması'], 'Rowntree, gelirin asgari beslenme ve barınma için bile yetmediği durumu birincil, gelirin yeterli olduğu halde başka harcamalar nedeniyle düşülen yoksulluğu ikincil yoksulluk olarak ayırdı.'),
  ('Paul Lazarsfeld, Marie Jahoda ve Hans Zeisel\'in 1930\'larda Avusturya\'da bir fabrika kapandıktan sonra bütün köyün işsiz kaldığı Marienthal\'de yaptığı araştırmanın temel bulgusu hangisidir?', 'Uzun süreli işsizliğin isyandan çok kayıtsızlık ve umutsuzluk doğurması', ['İşsizlerin hemen devrimci bir hareket örgütlemesi', 'İşsizliğin köy yaşamında hiçbir değişikliğe yol açmaması', 'İşsizlerin boş zamanlarını kütüphanelere giderek ve yeni beceriler edinerek verimli biçimde değerlendirmesi'], 'Araştırmacılar, işsizlerin kütüphaneye gitmeyi bile bıraktığını, yürüyüş hızlarının yavaşladığını ve günlerinin anlamını yitirdiğini gözlemledi.'),
  ('Edward Herman ve Noam Chomsky\'nin "Rızanın İmalatı" adlı eserinde geliştirdikleri propaganda modeline göre ana akım medyanın içeriğini biçimlendiren etkenlerden biri hangisidir?', 'Reklam gelirine bağımlılık', ['Okurların doğrudan yazı işlerini yönetmesi', 'Gazetecilerin tümüyle bağımsız ve denetimsiz çalışması', 'Haberlerin rastgele seçilmesi'], 'Herman ve Chomsky; mülkiyet, reklam gelirine bağımlılık, resmî kaynaklara dayanma, eleştirilere karşı yaptırımlar ve ortak düşman ideolojisi gibi süzgeçlerin haberleri biçimlendirdiğini savundu.'),
  ('Marshall McLuhan\'ın "Araç mesajdır" sözü neyi anlatır?', 'İletişim aracının biçiminin, içerikten bağımsız olarak toplumu ve algıyı dönüştürdüğünü', ['Bir mesajın etkisinin yalnızca içerdiği sözcüklere ve bilgilerin doğruluğuna bağlı olduğunu', 'Bütün iletişim araçlarının aynı içeriği aynı etkiyle aktardığını', 'Mesajların yalnızca yazılı araçlarla iletilebileceğini'], 'McLuhan\'a göre matbaa, radyo ya da televizyon gibi araçlar, taşıdıkları içerikten çok kendi biçimleriyle insanların algılama ve ilişki kurma biçimlerini değiştirir.'),
  ('Cloward ve Ohlin\'in "farklılaşmış fırsatlar" kuramına göre bir gencin hangi tür suç alt kültürüne katılacağını belirleyen etken hangisidir?', 'Mahallesinde hangi yasa dışı fırsat yapılarına erişebildiği', ['Doğuştan getirdiği kişilik özellikleri ve kalıtsal olarak aktarılan saldırganlık eğilimi', 'Ailesinin dinî inançları', 'Okulda aldığı notların ortalaması'], 'Cloward ve Ohlin, yasal fırsatlar gibi yasa dışı fırsatların da eşit dağılmadığını; örgütlü suçun bulunduğu, şiddetin yaygın olduğu ya da hiçbir fırsatın bulunmadığı mahallelerin farklı alt kültürler doğurduğunu savundu.'),
  ('David Matza\'nın suç işleyen gençlerin durumunu anlatmak için kullandığı "sürüklenme" kavramına göre bu gençler nasıl tanımlanır?', 'Geleneksel değerlerle suç arasında gidip gelen, ikisine de tam bağlanmamış kişiler', ['Doğuştan suça yatkın ve değiştirilemez kişiler', 'Toplumun bütün değerlerini bilinçli ve kalıcı biçimde reddetmiş, suçu bir yaşam biçimi olarak benimsemiş kişiler', 'Hiçbir zaman kural çiğnemeyen kişiler'], 'Matza\'ya göre gençlerin çoğu suç alt kültürüne tümüyle bağlanmaz; toplumsal denetimin gevşediği anlarda suça kayar, büyüdükçe çoğu bundan vazgeçer.'),
  ('Herbert Gans\'ın "Kentli Köylüler" adlı eserinde Boston\'daki İtalyan kökenli işçi mahallesi için ulaştığı sonuç hangisidir?', 'Sakinlerin akraba ve akran gruplarına dayanan köy benzeri bir yaşam sürdürdüğü', ['Mahallenin tümüyle çözülmüş, örgütsüz ve yıkılması gereken bir çöküntü alanı olduğu', 'Sakinlerin kentli orta sınıf yaşamını tümüyle benimsediği', 'Mahallede hiçbir komşuluk ilişkisinin bulunmadığı'], 'Gans, yetkililerin "çöküntü alanı" sayıp yıktırdığı West End\'in aslında güçlü aile ve akran bağlarıyla örülü bir topluluk olduğunu gösterdi.'),
  ('Amitai Etzioni\'nin öncülerinden olduğu komüniteryanizm (topluluk-yanlısı düşünce), liberal bireyciliğe karşı neyi vurgular?', 'Hakların yanında topluluğa karşı sorumlulukların ve ortak değerlerin önemini', ['Devletin bütün ekonomik etkinliği yönetmesi gerektiğini', 'Bireysel hakların tümüyle kaldırılması gerektiğini', 'Toplumun yalnızca piyasa ilişkileriyle, devletin ve topluluğun hiçbir müdahalesi olmadan düzenlenmesi gerektiğini'], 'Etzioni, aşırı bireyciliğin toplumsal bağları zayıflattığını; haklar ile sorumluluklar arasında denge kuran, aile, okul ve yerel topluluğu güçlendiren bir anlayış gerektiğini savundu.'),
  ('Bir kişinin beslenme alışkanlığını her gün okuduğu yeni bilimsel araştırmalara ve uzman önerilerine göre sürekli değiştirmesi Giddens\'ın hangi kavramıyla açıklanır?', 'Kurumsal düşünümsellik', ['Ontolojik güvenlik arayışı', 'Pratik bilinç', 'Yapının ikiliği'], 'Giddens\'a göre modern toplumda uzman bilgisi sürekli olarak gündelik uygulamalara geri döner ve bireyler yaşamlarını bu bilgiye göre yeniden düzenler.'),
  ('Ulrich Beck\'in bireyselleşme tezine göre günümüzde bireyin yaşam öyküsü nasıl değişmiştir?', 'Hazır yaşam yolları yerini bireyin kendi kurmak zorunda olduğu bir öyküye bırakmıştır', ['Bireyin bütün kararları ailesi tarafından verilmeye başlanmıştır', 'Sınıf aidiyeti ve aile geleneği bireyin yaşam yolunu her zamankinden daha kesin ve değişmez biçimde belirlemektedir', 'Bireyler hiçbir seçim yapmak zorunda kalmamaktadır'], 'Beck\'e göre bireyler artık eğitim, meslek ve ilişkileri hakkında sürekli karar vermek, başarısızlıkları da kişisel sorun olarak üstlenmek zorundadır.'),
  ('Daniel Bell\'in "Kapitalizmin Kültürel Çelişkileri" adlı eserinde işaret ettiği çelişki hangisidir?', 'Üretimin disiplin isterken tüketim kültürünün hazzı öne çıkarması', ['Kapitalizmin hiçbir kültürel değer, sanat eseri ya da yaşam tarzı üretmemesi ve kültürü tümüyle dışlaması', 'Sanayi işçilerinin sanatla hiç ilgilenmemesi', 'Devletin kültür harcamalarını tümüyle kesmesi'], 'Bell\'e göre kapitalizmin ekonomik alanı Protestan çalışma ahlakına dayanırken, kredi ve reklamla beslenen kültürel alan hazcılığı yayar; bu da sistemin meşruiyetini sarsar.'),
  ('Michel Crozier\'nin "Bürokratik Olgu" adlı eserinde Fransız kamu kurumlarında gözlemlediği "bürokratik kısır döngü" neyi anlatır?', 'Kuralların artmasının sorunları çözmek yerine yeni katılıklar doğurması', ['Bürokrasinin zamanla kendiliğinden küçülüp yerini kurallardan bağımsız kişisel ilişkilere bırakması', 'Memurların hiçbir kurala uymaması', 'Kurumların her yıl yeniden kurulması'], 'Crozier\'ye göre kişisel olmayan kurallar sorunları çözmek için çoğaltıldıkça örgüt daha da katılaşır, kalan belirsizlik alanlarını denetleyenler güç kazanır ve döngü sürer.'),
  ('Bruno Latour\'un öncüleri arasında yer aldığı "aktör-ağ kuramı"nın ayırıcı özelliği hangisidir?', 'Nesneler gibi insan olmayan varlıkları da ağın etkin öğeleri saymasını', ['Yalnızca bireylerin bilinçli niyetlerini ve iç dünyalarını inceleyip nesneleri tümüyle dışarıda bırakmasını', 'Toplumu yalnızca ekonomik sınıflarla açıklamasını', 'Doğa bilimlerini sosyolojinin dışında tutmasını'], 'Latour ve arkadaşları, bir bilimsel bulgunun ya da teknolojinin insanlar, aletler, belgeler ve mikroplar gibi farklı öğelerin birbirine bağlandığı ağlar içinde oluştuğunu savundu.'),
  ('Gayatri Chakravorty Spivak\'ın ünlü "Madun konuşabilir mi?" sorusunda, Gramsci\'den aldığı "madun" kavramıyla kastettiği kesim hangisidir?', 'Egemen söylemlerin dışında kalıp sesini duyuramayan ezilen gruplar', ['Ülkeyi yöneten siyasal seçkinler ve onların çevresindeki varlıklı bürokratlar', 'Uluslararası şirketlerin yöneticileri', 'Akademik çevrelerdeki ünlü kuramcılar'], 'Spivak, sömürge ve sömürge sonrası bağlamlarda özellikle yoksul kadınların hem sömürgeci hem de yerli erkek egemen söylemler tarafından temsil edilip kendi seslerinin bastırıldığını tartıştı.'),
  ('Richard Hoggart\'ın 1964\'te kurucu müdürü olduğu ve kültürel çalışmalar alanının doğuşunda belirleyici olan kurum hangisidir?', 'Birmingham Çağdaş Kültürel Çalışmalar Merkezi', ['Frankfurt Toplumsal Araştırmalar Enstitüsü', 'Londra Ekonomi ve Siyaset Bilimi Okulu', 'Chicago Üniversitesi Sosyoloji Bölümü'], 'Hoggart\'ın kurduğu merkez daha sonra Stuart Hall\'un yönetiminde gençlik alt kültürleri, medya ve popüler kültür üzerine öncü çalışmalar yaptı.'),
  ('Raymond Williams\'ın "Kültür sıradandır" sözüyle savunduğu görüş hangisidir?', 'Kültürün seçkin sanatla sınırlı olmayıp toplumun gündelik yaşam biçimi olduğu', ['Kültürün yalnızca saray çevrelerinde ve aristokrat salonlarında üretilip korunabilen bir birikim olduğu', 'Kültürün değersiz ve önemsiz bir alan olduğu', 'Kültürün yalnızca müzelerde korunması gerektiği'], 'Williams kültürü hem sanat ve öğrenme hem de sıradan insanların ortak anlamları ve yaşam tarzı olarak tanımladı; bu anlayış kültürel çalışmaların temelini oluşturdu.'),
  ('Dick Hebdige\'in "Altkültür: Tarzın Anlamı" adlı eserinde punk gibi gençlik altkültürlerinin giyim tarzlarını nasıl yorumladığı bilinir?', 'Nesnelerin anlamlarını değiştirerek egemen kültüre simgesel bir direniş', ['Yalnızca rastgele, anlamsız ve kısa süreli moda tercihlerinden ibaret, hiçbir toplumsal anlam taşımayan seçimler', 'Egemen kültüre tam bağlılığın göstergesi', 'Ekonomik refahın doğrudan sonucu'], 'Hebdige, çengelli iğne gibi sıradan nesnelerin bağlamından koparılıp yeni anlamlarla kullanılmasını bricolage olarak adlandırdı ve bunu simgesel bir direniş biçimi olarak çözümledi.'),
  ('Aşağıdaki Türk sosyolog-eser eşleştirmelerinden hangisi doğrudur?', 'Mümtaz Turhan - Kültür Değişmeleri', ['Ziya Gökalp - Türkiye Nasıl Kurtarılabilir?', 'Prens Sabahattin - Türkçülüğün Esasları', 'Niyazi Berkes - Modern Mahrem'], '"Kültür Değişmeleri" Mümtaz Turhan\'ındır. "Türkiye Nasıl Kurtarılabilir?" Prens Sabahattin\'e, "Türkçülüğün Esasları" Gökalp\'e, "Modern Mahrem" Nilüfer Göle\'ye aittir.'),
  ('Comte\'a göre toplumun pozitif aşamada manevi ve düşünsel yönlendirmesi kimlerin elinde olmalıdır?', 'Bilim insanlarının ve pozitif filozofların', ['Din adamlarının', 'Askerî komutanların', 'Toprak sahibi soyluların'], 'Comte, teolojik aşamada rahiplerin, metafizik aşamada hukukçu ve filozofların üstlendiği yönlendirici rolü pozitif aşamada bilim insanlarının üstleneceğini düşündü.'),
  ('Anthony Giddens\'ın 1997-2003 yılları arasında müdürlüğünü yaptığı ünlü eğitim kurumu hangisidir?', 'Londra Ekonomi Okulu', ['Harvard Üniversitesi', 'Sorbonne Üniversitesi', 'Frankfurt Üniversitesi'], 'Giddens Cambridge\'deki uzun akademik kariyerinin ardından Londra Ekonomi ve Siyaset Bilimi Okulu\'nun müdürü oldu.'),
  ('Ziya Gökalp\'in "Türkçülüğün Esasları" adlı eseri hangi yılda yayımlanmıştır?', '1923', ['1876', '1908', '1950'], 'Türkçülüğün Esasları Gökalp\'in ölümünden kısa süre önce, 1923\'te yayımlandı ve görüşlerinin olgun bir özeti olarak kabul edilir.'),
  ('Tocqueville\'in 1831\'de Gustave de Beaumont ile birlikte ABD\'ye yaptığı ve "Amerika\'da Demokrasi"nin doğmasına yol açan yolculuğun resmî amacı neydi?', 'Amerikan hapishane sistemini incelemek', ['Fransa adına bir ticaret anlaşması imzalamak', 'Kızılderili dillerini derlemek', 'Amerikan ordusunun yapısını incelemek'], 'Tocqueville ve Beaumont, Fransız hükümeti adına ABD\'deki cezaevlerini incelemek üzere yola çıktı; Tocqueville bu yolculukta edindiği gözlemlerle Amerikan demokrasisini çözümleyen eserini yazdı.'),
  ('Durkheim\'ın 1887\'de Fransa\'da bir üniversitede sosyal bilim dersleri vermeye başlaması sosyolojinin akademik kurumsallaşmasında önemli bir adımdır. Bu üniversite hangisidir?', 'Bordeaux Üniversitesi', ['Strazburg Üniversitesi', 'Lyon Üniversitesi', 'Montpellier Üniversitesi'], 'Durkheim 1887\'de Bordeaux Üniversitesi\'nde sosyal bilim ve pedagoji dersleri vermeye başladı; 1902\'de Sorbonne\'a geçti.'),
  ('Prens Sabahattin hangi ailenin üyesidir?', 'Osmanlı hanedanı', ['Kırım hanları', 'Mısır hidivleri', 'Karamanoğulları'], 'Prens Sabahattin, annesi Sultan Abdülmecid\'in kızı Seniha Sultan olan bir hanedan mensubudur; bu nedenle "prens" unvanıyla anılır.'),
];
